window.PYQ_DATA.add({"id":"px-ncert12-bio-environmental-issues","kind":"practice","exam":"NEET","year":null,"title":"Environmental Issues · Practice","chapter":"Environmental Issues","subject":"Biology","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","marking":{"mcq":[4,-1]},"rules":{},"note":"","questions":[{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-001","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":1,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"NCERT suggests that household waste should be segregated into three categories. These are:","image":"","options":["Solid, liquid and gaseous","Organic, inorganic and radioactive","Domestic, industrial and hospital","Biodegradable, recyclable and non-biodegradable"],"optionsInImage":false,"answer":["4"],"explanation":"NCERT says all the waste we generate can be grouped as (a) biodegradable, (b) recyclable and (c) non-biodegradable.\nSorting waste this way lets biodegradable matter decompose and recyclable material be reused.\nIt also reduces the load of non-biodegradable waste that must be dumped.\nThe other groupings are based on physical state or source, not on how the waste is handled.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-002","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":2,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following best describes reforestation?","image":"","options":["Converting forested land into agricultural fields","Restoring a forest that once existed at a place but was removed at some point","Planting trees on land that has never carried forest","Protecting an existing forest by banning all human entry"],"optionsInImage":false,"answer":["2"],"explanation":"Reforestation is the process of restoring a forest at a site where it once existed but was removed.\nIt may happen naturally on deforested land.\nHumans can speed it up by planting trees, keeping in mind the biodiversity that earlier existed in that area.\nPlanting trees on land that never had forest is a different process and does not fit this definition.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-003","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":3,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which greenhouse gas makes the largest relative contribution, about 60%, to total global warming?","image":"","options":["Methane","Carbon dioxide","Chlorofluorocarbons","Nitrous oxide"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT shows the relative contributions of the greenhouse gases in a pie chart: CO2 about 60%, CH4 about 20%, CFCs about 14% and N2O about 6%.\nCarbon dioxide is therefore the largest contributor.\nMethane comes second at about 20%, so it is the most tempting wrong option.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-004","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":4,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"At lower doses, nuclear radiation creates various disorders in living organisms. Which disorder does NCERT name as the most frequent of all?","image":"","options":["Cancer","Snow-blindness","Fluorosis","Blue baby syndrome"],"optionsInImage":false,"answer":["1"],"explanation":"At high doses, nuclear radiation is lethal.\nAt lower doses it causes various disorders, and NCERT names cancer as the most frequent.\nSnow-blindness is caused by high UV-B exposure, not by nuclear radiation.\nFluorosis and blue baby syndrome are linked to water contaminants (fluoride and nitrate).\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-005","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":5,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: The combined contribution of methane and CFCs to global warming is greater than that of carbon dioxide.\nStatement II: Among the major greenhouse gases, nitrous oxide makes the smallest relative contribution to global warming.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["4"],"explanation":"Statement I: CH4 (about 20%) plus CFCs (about 14%) gives about 34%. This is less than CO2's 60%, so Statement I is incorrect.\nStatement II: N2O contributes only about 6%, the smallest share among CO2, CH4, CFCs and N2O, so Statement II is correct.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-006","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":6,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Recycling of e-wastes in developing countries exposes workers to toxic substances.\nReason (R): Unlike developed countries, which have specially built recycling facilities, recycling in developing countries often involves manual participation.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true. NCERT notes that e-waste recycling in developing countries exposes workers to the toxic substances present in e-wastes.\nR is true. Developed countries have dedicated recycling facilities, while developing countries rely largely on manual handling.\nThe manual handling is exactly why workers come into contact with the toxins, so R explains A.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-007","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":7,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to NCERT, the main reason CNG causes less vehicular pollution than petrol or diesel is that CNG:","image":"","options":["contains no carbon atoms","burns most efficiently, leaving very little of it unburnt","produces no carbon dioxide on combustion","is stored in liquid form at room temperature"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT explains that CNG burns most efficiently in automobiles, unlike petrol or diesel, so very little of it is left unburnt.\nCNG is mainly methane ($CH_4$). It contains carbon and gives $CO_2$ when it burns, so options (1) and (3) are wrong.\nCNG is a compressed gas, not a liquid, so option (4) is wrong.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-008","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":8,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Chipko movement\nB. Amrita Devi Bishnoi's sacrifice (1731)\nC. Ecological sanitation (Ecosan) toilets\nD. Integrated wastewater treatment using marshes\nList-II\ni. Arcata, California\nii. Kerala and Sri Lanka\niii. Garhwal Himalayas\niv. Rajasthan","image":"","options":["A-iii, B-iv, C-ii, D-i","A-iv, B-iii, C-i, D-ii","A-iii, B-iv, C-i, D-ii","A-ii, B-iv, C-iii, D-i"],"optionsInImage":false,"answer":["1"],"explanation":"A–iii: The Chipko movement (1974) began when village women hugged trees in the Garhwal Himalayas.\nB–iv: Amrita Devi and other Bishnois gave their lives to protect trees in a Rajasthan village.\nC–ii: Ecosan dry composting toilets are in use in parts of Kerala and Sri Lanka.\nD–i: The Arcata town wastewater project in California, run with FOAM, uses six connected marshes.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-009","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":9,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements about agrochemicals are correct?\n(i) Use of inorganic fertilisers and pesticides increased manifold in the wake of the green revolution.\n(ii) Pesticides, herbicides and fungicides are toxic only to the target pests and spare all other organisms.\n(iii) Adding increasing amounts of chemical fertilisers can lead to eutrophication of aquatic ecosystems.\n(iv) Non-target organisms harmed by these chemicals include important components of the soil ecosystem.","image":"","options":["One","Two","Three","Four"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: the green revolution greatly increased the use of inorganic fertilisers and pesticides.\n(ii) Incorrect: NCERT states these chemicals are also toxic to non-target organisms.\n(iii) Correct: fertiliser run-off enriches water bodies with nutrients, causing eutrophication.\n(iv) Correct: the non-target organisms affected are important components of the soil ecosystem.\nThree statements are correct.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-010","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":10,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Untreated sewage enters a clean river at one point. Arrange the following events, observed while moving downstream from the outfall, in the correct sequence:\n(i) Clean-water organisms such as fish reappear\n(ii) Decomposer microbes multiply rapidly on the organic load\n(iii) Organic matter is largely decomposed and BOD declines\n(iv) Dissolved oxygen falls sharply and fish die","image":"","options":["(iv) → (ii) → (iii) → (i)","(ii) → (iv) → (iii) → (i)","(ii) → (iii) → (iv) → (i)","(iii) → (ii) → (iv) → (i)"],"optionsInImage":false,"answer":["2"],"explanation":"At the outfall, the sudden supply of organic matter lets decomposers multiply (ii).\nTheir respiration consumes oxygen, so DO drops and fish die (iv). The cause comes before the effect, which rules out option (1).\nFurther downstream, the organic matter gets used up, so BOD falls (iii).\nDO then recovers and clean-water organisms return (i).\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-011","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":11,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II:\nList-I\n(A) Open dump\n(B) Sanitary landfill\n(C) Incinerator\n(D) Polyblend\nList-II\n(i) Recycled plastic powder mixed with bitumen\n(ii) Breeding ground for rats and flies\n(iii) Disposal of hospital waste\n(iv) Compacted waste covered with dirt daily","image":"","options":["A-ii, B-iv, C-iii, D-i","A-iv, B-ii, C-iii, D-i","A-ii, B-iii, C-iv, D-i","A-iii, B-iv, C-ii, D-i"],"optionsInImage":false,"answer":["1"],"explanation":"A-ii: incompletely burnt open dumps attract rats and flies.\nB-iv: in a sanitary landfill, waste is compacted in a trench and covered with dirt daily.\nC-iii: incinerators are crucial for disposing of hospital waste.\nD-i: polyblend is a powder of recycled plastic blended with bitumen for roads.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-012","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":12,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In the NCERT figure on biomagnification of DDT in an aquatic food chain, match each component (List-I) with its DDT concentration (List-II).\nList-I:\nA. Water\nB. Zooplankton\nC. Small fish\nD. Fish-eating birds\nList-II:\n(i) 25 ppm\n(ii) 0.04 ppm\n(iii) 0.003 ppb\n(iv) 0.5 ppm","image":"","options":["A-iii, B-iv, C-ii, D-i","A-ii, B-iii, C-iv, D-i","A-iii, B-ii, C-iv, D-i","A-i, B-ii, C-iv, D-iii"],"optionsInImage":false,"answer":["3"],"explanation":"The figure shows DDT concentration rising at each successive trophic level.\nA–iii: water carries only 0.003 ppb.\nB–ii: zooplankton accumulate 0.04 ppm.\nC–iv: small fish accumulate 0.5 ppm (large fish 2 ppm).\nD–i: fish-eating birds, at the top of the chain, reach 25 ppm.\nOption (1) wrongly swaps the zooplankton and small-fish values.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-013","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":13,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"A state government plans to limit global warming. Which set contains ONLY measures that help control global warming?","image":"","options":["Cutting down fossil fuel use, improving efficiency of energy usage, planting trees, slowing human population growth","Cutting down fossil fuel use, clearing forests for new farmland, planting trees, improving efficiency of energy usage","Improving efficiency of energy usage, burning crop residue in open fields, reducing deforestation, slowing human population growth","Planting trees, greatly increasing nitrogen fertiliser use, cutting down fossil fuel use, reducing deforestation"],"optionsInImage":false,"answer":["1"],"explanation":"NCERT lists these control measures: cutting down fossil fuel use, improving efficiency of energy usage, reducing deforestation, planting trees and slowing human population growth.\nOption (1) contains only these measures.\nOption (2): clearing forests removes CO2 sinks.\nOption (3): open burning of crop residue releases CO2 and other pollutants.\nOption (4): heavy nitrogen fertiliser use raises N2O emissions, and N2O is a greenhouse gas.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-014","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":14,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to NCERT, which greenhouse gas makes the second largest relative contribution to total global warming?","image":"","options":["Carbon dioxide","Chlorofluorocarbons","Methane","Nitrous oxide"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT gives the approximate relative contributions to global warming as follows:\n$CO_2$ about 60%, methane about 20%, CFCs about 14% and $N_2O$ about 6%.\nCarbon dioxide is the largest contributor, so it is not the answer.\nMethane, at about 20%, comes second. CFCs are a close but smaller third.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-015","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":15,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"After the Earth's surface is heated by sunlight, it re-emits heat. Gases such as carbon dioxide and methane absorb a major fraction of this heat, and the heat is in the form of:","image":"","options":["Ultraviolet radiation","Visible light","Infrared radiation","X-rays"],"optionsInImage":false,"answer":["3"],"explanation":"Incoming solar radiation heats the Earth's surface.\nThe warm surface then re-emits heat as infrared radiation.\nGreenhouse gases absorb a large part of this infrared radiation and radiate it back towards the surface, which keeps the Earth warm.\nUltraviolet radiation is the part of sunlight that ozone absorbs; it is not what the surface re-emits.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-016","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":16,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Nuclear waste is regarded as an extremely potent pollutant that must be handled with utmost caution.\nReason (R): Radiation given off by nuclear waste causes mutations to occur at a very high rate.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true: NCERT calls nuclear waste an extremely potent pollutant that must be dealt with utmost caution.\nR is true: its radiation is extremely damaging to organisms because it causes mutations at a very high rate.\nThis high mutation rate (leading to disorders such as cancer, and death at high doses) is exactly why the waste is so dangerous.\nSo R correctly explains A.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-017","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":17,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"NCERT states that even a brief exposure to an extremely high sound level can damage the eardrums and permanently impair hearing. Which option correctly pairs that sound level with the example NCERT gives?","image":"","options":["About 80 dB, from busy road traffic","About 100 dB, from a loudspeaker at a function","150 dB or more, from a jet plane or rocket taking off","About 60 dB, from normal conversation"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT gives the take-off of a jet plane or rocket as the example of extreme sound.\nIt puts this level at 150 dB or more.\nAt this level, even a brief exposure can damage the eardrums and cause permanent loss of hearing.\nLevels such as 60 to 100 dB come from conversation, traffic or loudspeakers. These can harm hearing over long exposure, but they are not the 'brief exposure' example given.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-018","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":18,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"As per Euro II norms mentioned in NCERT, the maximum permitted sulphur content in diesel is:","image":"","options":["50 ppm","150 ppm","350 ppm","42 ppm"],"optionsInImage":false,"answer":["3"],"explanation":"Euro II norms limit sulphur to 350 ppm in diesel and 150 ppm in petrol.\n150 ppm is the petrol limit, not the diesel limit.\n50 ppm is the future target of the roadmap for both fuels.\n42 is the per cent limit for aromatic hydrocarbons, not a sulphur value in ppm.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-019","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":19,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Biochemical Oxygen Demand (BOD) of a water sample is used as a measure of:","image":"","options":["the amount of biodegradable organic matter, estimated from the oxygen microbes need to break it down","the amount of oxygen released into water by algae during photosynthesis","the concentration of toxic heavy metal ions in the water","the total amount of dissolved salts such as sodium and calcium"],"optionsInImage":false,"answer":["1"],"explanation":"Microorganisms use oxygen while they decompose biodegradable organic matter.\nBOD measures this oxygen demand. It therefore indicates how much organic matter is present in the water.\nA higher BOD means the water has a greater polluting potential.\nBOD does not measure oxygen released by algae. It also does not measure metals or dissolved salts.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-020","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":20,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements about noise pollution is INCORRECT?","image":"","options":["Noise can cause both physiological and psychological disorders in humans.","Hearing can be permanently damaged only by brief exposure to sounds of 150 dB or more; long exposure to the lower noise levels of cities is harmless to hearing.","Noise can lead to sleeplessness and an altered breathing pattern.","Use of sound-absorbent materials helps reduce noise pollution."],"optionsInImage":false,"answer":["2"],"explanation":"(1) Correct: NCERT says noise causes psychological and physiological disorders.\n(2) Incorrect: NCERT says chronic exposure to the relatively lower noise levels of cities may also permanently damage hearing.\n(3) Correct: sleeplessness and an altered breathing pattern are listed effects of noise.\n(4) Correct: sound-absorbent materials are a listed control measure.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-021","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":21,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The catalytic converters fitted in automobiles use which set of expensive metals as catalysts?","image":"","options":["Platinum, palladium and rhodium","Gold, silver and platinum","Nickel, iron and copper","Lead, mercury and cadmium"],"optionsInImage":false,"answer":["1"],"explanation":"According to NCERT, catalytic converters contain platinum, palladium and rhodium as catalysts.\nThese costly metals help convert harmful exhaust gases into less harmful ones.\nNickel, iron and copper are not the metals named by NCERT.\nLead actually inactivates the catalyst, so the set with lead, mercury and cadmium cannot be correct.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-022","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":22,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: The National Forest Policy (1988) of India recommends 67% forest cover for the plains and 33% for the hills.\nStatement II: India's forest cover fell from about 30% at the beginning of the twentieth century to about 19.4% by its end.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["4"],"explanation":"Statement I is incorrect: the values are reversed. The policy recommends 33% forest cover for the plains and 67% for the hills.\nStatement II is correct: forest cover declined from about 30% to 19.4% over the twentieth century, according to NCERT.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-023","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":23,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II with reference to the auto fuel policy described in NCERT.\nList-I\nA. Sulphur in diesel under Euro II\nB. Sulphur in petrol under Euro II\nC. Aromatic hydrocarbons under Euro II\nD. Roadmap target for sulphur in petrol and diesel\nList-II\ni. 150 ppm\nii. 50 ppm\niii. 350 ppm\niv. 42 per cent of the fuel","image":"","options":["A-iii, B-i, C-iv, D-ii","A-i, B-iii, C-iv, D-ii","A-iii, B-ii, C-iv, D-i","A-ii, B-i, C-iii, D-iv"],"optionsInImage":false,"answer":["1"],"explanation":"A-iii: Euro II limits sulphur in diesel to 350 ppm.\nB-i: Euro II limits sulphur in petrol to 150 ppm.\nC-iv: aromatic hydrocarbons are to be kept at 42% of the fuel.\nD-ii: the roadmap aims to bring sulphur down to 50 ppm in both petrol and diesel.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-024","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":24,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In an electrostatic precipitator used to clean exhaust from thermal power plants, how is particulate matter removed from the gas stream?","image":"","options":["Electrode wires at high voltage give dust particles a negative charge, and grounded collecting plates attract them","Water or lime is sprayed on the gas so the particles dissolve and drain away","A platinum–palladium catalyst oxidises the particles into carbon dioxide and water","Fast-moving air throws the particles outward by centrifugal force onto filter cloth"],"optionsInImage":false,"answer":["1"],"explanation":"Electrode wires kept at several thousand volts produce a corona that releases electrons.\nThese electrons attach to dust particles, giving them a net negative charge.\nGrounded collecting plates attract the charged particles. Air must move slowly between the plates so the dust can settle. Over 99% of particulate matter is removed.\nOption (2) describes a scrubber, which removes gases such as $SO_2$. Option (3) describes a catalytic converter.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-025","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":25,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Industrial exhaust is passed through a spray of water or lime to remove a harmful gas before release into the air. Which device is used, and which gas does it mainly remove?","image":"","options":["Electrostatic precipitator; carbon monoxide","Catalytic converter; sulphur dioxide","Scrubber; sulphur dioxide","Scrubber; nitric oxide"],"optionsInImage":false,"answer":["3"],"explanation":"A scrubber passes exhaust through a spray of water or lime. This removes gases such as sulphur dioxide.\nAn electrostatic precipitator removes particulates, not gases like CO.\nA catalytic converter is fitted in vehicles and does not use a water or lime spray.\nNCERT names sulphur dioxide, not nitric oxide, as the gas removed by scrubbers.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-026","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":26,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are given in NCERT as advantages of CNG over petrol or diesel?\n(i) It burns most efficiently, with very little left unburnt\n(ii) It is cheaper than petrol or diesel\n(iii) It cannot be siphoned off by thieves\n(iv) It cannot be adulterated like petrol or diesel\n(v) Pipelines and pumps for its supply are easy to lay down and maintain","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: CNG burns most efficiently.\n(ii) Correct: it is cheaper than petrol or diesel.\n(iii) Correct: it cannot be siphoned off by thieves.\n(iv) Correct: it cannot be adulterated.\n(v) Incorrect: NCERT names the difficulty of laying pipelines and ensuring uninterrupted supply as the main problem with switching to CNG.\nSo 4 statements are advantages.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-027","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":27,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements about the natural ageing (eutrophication) of a lake is INCORRECT?","image":"","options":["A young lake is cold and clear and supports relatively little life","Streams draining into the lake bring nutrients such as nitrogen and phosphorus, which encourage aquatic organisms","As the lake ages it becomes deeper and colder, so cold-water organisms replace warm-water ones","Over centuries, marsh plants take root and the lake may finally become land"],"optionsInImage":false,"answer":["3"],"explanation":"Option (1) is correct: a young lake is cold, clear and supports little life.\nOption (2) is correct: incoming nitrogen and phosphorus raise the lake's fertility.\nOption (3) is incorrect: silt and organic debris make the lake shallower and warmer, so warm-water organisms replace cold-water ones.\nOption (4) is correct: the lake fills, marsh plants take root, and the lake eventually becomes land.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-028","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":28,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: Deforestation raises the carbon dioxide concentration in the atmosphere, because trees hold a large amount of carbon in their biomass.\nStatement II: Deforestation disturbs the hydrologic cycle but has no role in soil erosion.","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["2"],"explanation":"Statement I is correct. Trees store a lot of carbon, and this carbon is released when forests are cut and burnt.\nStatement II is incorrect. Deforestation does disturb the hydrologic cycle, but it also causes soil erosion. In extreme cases it can lead to desertification.\nLoss of biodiversity through habitat destruction is another effect of deforestation.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-029","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":29,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Motor vehicles equipped with a catalytic converter should use unleaded petrol.\nReason (R): Lead present in petrol inactivates the catalyst of the converter.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true. NCERT recommends unleaded petrol for vehicles fitted with catalytic converters.\nR is true. Lead inactivates the platinum–palladium–rhodium catalyst.\nAn inactivated catalyst can no longer convert the harmful gases, so R directly explains why A is necessary.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-030","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":30,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Noise was brought under legal control in India by amending an existing Act in 1987 so that noise counts as a pollutant. Which Act was amended?","image":"","options":["Water (Prevention and Control of Pollution) Act, 1974","Environment (Protection) Act, 1986","Wildlife (Protection) Act, 1972","Air (Prevention and Control of Pollution) Act, 1981"],"optionsInImage":false,"answer":["4"],"explanation":"The Air (Prevention and Control of Pollution) Act came into force in 1981.\nBecause noise has many harmful effects, this Act was amended in 1987.\nThe amendment made noise an air pollutant.\nThe Water Act (1974) and the Environment Protection Act (1986) were not the ones amended for noise.\nThe Wildlife Act (1972) deals with protecting wildlife, not pollution.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-031","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":31,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to NCERT, after pre-treatment, nuclear waste should be stored in suitably shielded containers buried within rocks at about what depth below the earth's surface?","image":"","options":["About 50 m","About 500 m","About 5 km","About 5 m"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT recommends that pre-treated nuclear waste be stored in suitably shielded containers.\nThese containers are buried within rocks about 500 m below the earth's surface.\n50 m and 5 m are far too shallow to isolate the waste. 5 km is not the figure NCERT gives.\nNCERT also notes that this method faces stiff opposition from the public.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-032","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":32,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I (greenhouse gas) with List-II (approximate relative contribution to total global warming) and choose the correct option.\nList-I:\nA. Carbon dioxide\nB. Methane\nC. CFCs\nD. Nitrous oxide\nList-II:\n(i) 6%\n(ii) 14%\n(iii) 20%\n(iv) 60%","image":"","options":["A-(iv), B-(iii), C-(ii), D-(i)","A-(iv), B-(ii), C-(iii), D-(i)","A-(iii), B-(iv), C-(i), D-(ii)","A-(iv), B-(i), C-(ii), D-(iii)"],"optionsInImage":false,"answer":["1"],"explanation":"The NCERT pie chart of relative contributions shows the following shares.\nCarbon dioxide is the largest contributor at about 60%, so A-(iv).\nMethane contributes about 20%, so B-(iii).\nCFCs contribute about 14%, so C-(ii).\nNitrous oxide contributes about 6%, so D-(i).\nOption (2) wrongly gives CFCs a larger share than methane.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-033","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":33,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements about controlling air pollution are correct?\n(i) An electrostatic precipitator can remove over 99% of particulate matter from the exhaust of a thermal power plant.\n(ii) In an electrostatic precipitator, electrode wires at several thousand volts produce a corona that releases electrons.\n(iii) A scrubber can remove gases like sulphur dioxide using a spray of water or lime.\n(iv) The collecting plates of an electrostatic precipitator are kept at a high negative voltage.\n(v) According to CPCB, particles of 10 micrometres or more in diameter cause the greatest harm to human health.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: an ESP removes over 99% of particulate matter.\n(ii) Correct: the corona releases electrons, which attach to dust particles and give them a negative charge.\n(iii) Correct: a scrubber removes SO$_2$ using a water or lime spray.\n(iv) Incorrect: the collecting plates are grounded.\n(v) Incorrect: the most harmful particles are those 2.5 micrometres or less (PM 2.5).\nThree statements are correct.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-034","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":34,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are effects of noise on humans as described in NCERT?\n(i) Sleeplessness\n(ii) Increased heart beating\n(iii) Snow blindness\n(iv) Altered breathing pattern\n(v) Stress\n(vi) Biomagnification","image":"","options":["3","4","5","6"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Yes: sleeplessness is an effect of noise.\n(ii) Yes: noise increases the heart rate.\n(iii) No: snow blindness is caused by too much UV-B falling on the cornea.\n(iv) Yes: noise alters the breathing pattern.\n(v) Yes: together these effects put humans under considerable stress.\n(vi) No: biomagnification is the build-up of a toxin such as DDT along the food chain.\nSo 4 of the six are effects of noise.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-035","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":35,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to the National Forest Policy (1988) of India, what is the recommended forest cover for the hills?","image":"","options":["33%","19.4%","67%","50%"],"optionsInImage":false,"answer":["3"],"explanation":"The National Forest Policy (1988) set separate forest cover targets for plains and hills.\nIt recommends 33% forest cover for the plains and 67% for the hills.\n33% is the target for the plains, not the hills.\n19.4% is roughly India's actual forest cover at the end of the 20th century, not a target.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-036","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":36,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Waterlogging of irrigated fields can make the soil unfit for growing crops.\nReason (R): Irrigation without proper drainage draws salt up to the surface, where it forms a crust or collects at the roots of plants.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true. Waterlogging, a problem that came with the Green Revolution, is very damaging to agriculture.\nR is true. Irrigation without proper drainage pulls salts upward. They are deposited as a thin crust on the land or collect at the roots.\nThis rise in salt content (soil salinity) harms crop growth, so R correctly explains A.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-037","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":37,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"A mountaineer who climbs for many days over snow-covered slopes without eye protection develops snow-blindness. This condition is caused by a high dose of UV-B, which leads to inflammation of the:","image":"","options":["Retina","Lens","Cornea","Optic nerve"],"optionsInImage":false,"answer":["3"],"explanation":"In the human eye, the cornea absorbs UV-B radiation.\nA high dose of UV-B causes inflammation of the cornea. NCERT calls this snow-blindness, and such exposure may permanently damage the cornea.\nThe lens is the tempting wrong choice. UV damage to the lens is linked to cataract, which is a different condition from snow-blindness.\nThe retina and optic nerve are not involved in snow-blindness.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-038","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":38,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I (greenhouse gas) with List-II (approximate relative contribution to global warming):\nList-I\n(A) Carbon dioxide\n(B) Methane\n(C) Chlorofluorocarbons\n(D) Nitrous oxide\nList-II\n(i) 6%\n(ii) 14%\n(iii) 20%\n(iv) 60%","image":"","options":["A-(iv), B-(iii), C-(ii), D-(i)","A-(iv), B-(ii), C-(iii), D-(i)","A-(iii), B-(iv), C-(i), D-(ii)","A-(iv), B-(iii), C-(i), D-(ii)"],"optionsInImage":false,"answer":["1"],"explanation":"Carbon dioxide contributes about 60%, so A-(iv).\nMethane contributes about 20%, so B-(iii).\nCFCs contribute about 14%, so C-(ii).\nNitrous oxide contributes about 6%, so D-(i).\nOption (2) swaps methane and CFCs, and option (4) swaps CFCs and N2O.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-039","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":39,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Ahmed Khan\nB. Ramesh Chandra Dagar\nC. Amrita Devi Bishnoi\nD. Friends of the Arcata Marsh (FOAM)\nList-II\n(i) Sacrificed her life protecting trees in Khejarli village near Jodhpur\n(ii) Developed polyblend from recycled plastic for road laying\n(iii) Citizens' group that helped improve an integrated wastewater treatment plan\n(iv) Integrated organic farming; Haryana Kisan Welfare Club","image":"","options":["A-ii, B-iii, C-i, D-iv","A-iv, B-ii, C-i, D-iii","A-ii, B-i, C-iv, D-iii","A-ii, B-iv, C-i, D-iii"],"optionsInImage":false,"answer":["4"],"explanation":"A-ii: Ahmed Khan of Bangalore developed polyblend, a powder of recycled plastic that is mixed with bitumen for roads.\nB-iv: Ramesh Chandra Dagar of Sonipat practises integrated organic farming and founded the Haryana Kisan Welfare Club.\nC-i: Amrita Devi Bishnoi led the protest to save trees at Khejarli in 1731.\nD-iii: FOAM, a citizens' group, supported the integrated wastewater treatment plan at Arcata, California.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-040","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":40,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"A city council plans to lower noise levels. Its list of steps is:\n(i) Fitting mufflers (silencers) on vehicle exhausts and generators\n(ii) Lining the walls of auditoriums and recording studios with sound-absorbent material\n(iii) Banning loudspeakers after a fixed hour at night\n(iv) Declaring roads near hospitals and schools as horn-free zones\nWhich option correctly groups these steps?","image":"","options":["(i) and (ii) are legal measures; (iii) and (iv) are technical measures","(i) and (ii) reduce noise through materials or devices; (iii) and (iv) reduce noise by enforcing rules","Only (iv) reduces noise from transport, the main source of noise","(ii) reduces noise at its source, while (i) only absorbs noise after it spreads"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Mufflers cut down noise at its source, which is a device-based step.\n(ii) Sound-absorbent linings soak up sound inside a room, which is a material-based step.\n(iii) and (iv) depend on laws: fixing loudspeaker timings and making horn-free zones.\nOption (3) is wrong because mufflers on vehicles also reduce transport noise.\nOption (4) has the two steps the wrong way round.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-041","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":41,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements about cultural (accelerated) eutrophication are correct?\n(i) It is driven by effluents from industries and homes, sewage and agricultural run-off.\n(ii) Nitrates and phosphates are its prime contaminants.\n(iii) Like natural lake ageing, it takes thousands of years to show its effects.\n(iv) The overgrowth of algae and its later decomposition can rob the water of dissolved oxygen, so the lake may literally choke to death.\n(v) Heavy metal ions act as the main nutrients that cause it.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: Human activities supply the extra nutrients that drive it.\n(ii) Correct: Nitrates and phosphates are the prime contaminants.\n(iii) Incorrect: It greatly speeds up ageing. Natural eutrophication is the process that takes thousands of years.\n(iv) Correct: Algal overgrowth and decay deplete dissolved oxygen.\n(v) Incorrect: Heavy metals are toxic pollutants, not nutrients.\nSo three statements are correct.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-042","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":42,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In the human eye, a high dose of UV-B radiation absorbed by the cornea causes its inflammation. This condition is called:","image":"","options":["Night blindness","Colour blindness","Glaucoma","Snow-blindness"],"optionsInImage":false,"answer":["4"],"explanation":"The cornea absorbs UV-B radiation.\nA high dose of UV-B inflames the cornea, and this condition is called snow-blindness. Such exposure may permanently damage the cornea.\nNight blindness is caused by vitamin A deficiency.\nColour blindness is a genetic disorder.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-043","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":43,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): In 1987, the Air (Prevention and Control of Pollution) Act was amended to include noise as an air pollutant.\nReason (R): Noise is an undesired high level of sound that causes several harmful physiological and psychological effects in humans.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true: the Air Act of 1981 was amended in 1987 to cover noise.\nR is true: noise is undesired high-level sound that causes disorders such as hearing loss, sleeplessness and stress.\nNCERT says the amendment was made because of these dangerous effects of noise.\nSo R correctly explains A.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-044","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":44,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): A lake receiving large amounts of sewage and fertiliser runoff can age within decades and may finally be converted to land.\nReason (R): In cultural eutrophication, the dissolved oxygen of the lake rises steadily because of photosynthesis by the dense algal growth.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"A is true: nutrients such as nitrates and phosphates from sewage and fertilisers greatly speed up lake ageing (cultural or accelerated eutrophication). Silt and dead organic matter then fill the basin until it becomes land.\nR is false: although algae photosynthesise, the decomposition of dead algae and organic matter uses up oxygen. Dissolved oxygen therefore falls, killing fish and other animals.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-045","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":45,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In the absence of the natural greenhouse effect, the average temperature at the surface of the Earth would have been about:","image":"","options":["15°C","0°C","-18°C","-33°C"],"optionsInImage":false,"answer":["3"],"explanation":"The greenhouse effect occurs naturally and keeps the Earth's average surface temperature at about 15°C.\nWithout it, the average temperature would fall to about -18°C, which would make the planet far too cold for most life.\n15°C is the present average, so option (1) is a trap.\n-33°C is a distractor built from the 33°C difference between the two values.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-046","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":46,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Hospital wastes need careful treatment, and the use of incinerators is considered crucial for their disposal. This is mainly because hospital wastes","image":"","options":["are largely made of paper and food scraps that rot quickly","contain disinfectants, other harmful chemicals and pathogenic micro-organisms","consist mostly of metals that can be recovered by burning","are produced in such small amounts that landfilling is uneconomical"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT states that hospitals generate hazardous wastes. These contain disinfectants, other harmful chemicals and pathogenic micro-organisms.\nSuch wastes need careful treatment, so incineration is crucial to destroy them safely.\nOption (1) describes ordinary biodegradable municipal waste, which does not specially need incineration.\nOptions (3) and (4) do not match NCERT.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-047","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":47,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Sewage rich in biodegradable organic matter is discharged at one point into a flowing river. Which option correctly describes the changes downstream?","image":"","options":["Just below the outlet, BOD rises and dissolved oxygen falls sharply; farther downstream, dissolved oxygen gradually recovers as the organic matter is decomposed","Just below the outlet, BOD and dissolved oxygen both rise; farther downstream, both fall to zero","Just below the outlet, dissolved oxygen rises because microbes release oxygen while degrading sewage; BOD stays constant along the river","BOD falls immediately below the outlet and keeps falling downstream, while dissolved oxygen does not change"],"optionsInImage":false,"answer":["1"],"explanation":"Near the outlet, microbes decompose the added organic matter and consume a great deal of oxygen. This sharply raises BOD and lowers dissolved oxygen, causing mortality of fish and other aquatic creatures.\nAs the water flows on, the organic load is used up. BOD then declines and dissolved oxygen gradually returns towards normal.\nOption (3) is wrong because decomposers consume oxygen; they do not release it.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-048","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":48,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: An algal bloom is an excessive growth of free-floating planktonic algae in a nutrient-rich water body, and it gives the water a distinct colour.\nStatement II: Algal blooms improve the quality of water, because the algae add oxygen through photosynthesis and none of the bloom-forming algae are harmful.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Statement I is correct. Large amounts of nutrients cause excessive growth of planktonic algae, called an algal bloom. The bloom colours the water.\nStatement II is incorrect on two counts.\nFirst, blooms make water quality worse and cause fish mortality.\nSecond, some bloom-forming algae are extremely toxic to humans and animals.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-049","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":49,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements about the greenhouse effect and global warming are correct?\n(i) Carbon dioxide and methane together account for about 80% of the relative contribution to global warming.\n(ii) CFCs make a larger relative contribution to global warming than methane.\n(iii) A rise in global temperature leads to odd climatic changes such as the El Niño effect.\n(iv) Melting of polar ice caps and Himalayan snow caps due to warming can raise sea level and submerge many coastal areas.\n(v) If greenhouse gases were absent, the Earth's average surface temperature would be higher than 15°C.","image":"","options":["Two","Three","Four","Five"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: CO2 contributes about 60% and CH4 about 20%, giving about 80% together.\n(ii) Incorrect: CFCs contribute about 14%, which is less than methane's 20%.\n(iii) Correct: NCERT cites the El Niño effect as an example of odd climatic changes caused by warming.\n(iv) Correct: melting ice raises sea level and threatens coastal areas.\n(v) Incorrect: without greenhouse gases the temperature would drop to about -18°C, not rise above 15°C.\nSo three statements are correct.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-050","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":50,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: A brief exposure to the sound of a rocket taking off (150 dB or more) may permanently impair hearing, while normal conversation (about 60 dB) does not.\nStatement II: Since sound level is measured in decibels, a sound of 150 dB is only 2.5 times as intense as a sound of 60 dB.\nChoose the correct option:","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Statement I is correct: NCERT says a brief exposure to 150 dB or more can damage the eardrums. Conversation is far quieter and does not do this.\nStatement II is incorrect: the decibel scale is logarithmic, not linear.\nEach rise of 10 dB means about ten times more intensity.\nThe gap here is 150 − 60 = 90 dB, so the 150 dB sound is about $10^9$ times as intense, not 2.5 times.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-051","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":51,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Arrange the following events in the correct sequence leading to ozone depletion:\n(i) UV rays act on CFCs, releasing Cl atoms\n(ii) CFCs are discharged in the lower atmosphere\n(iii) Cl atoms degrade ozone, releasing molecular oxygen\n(iv) CFCs move upward and reach the stratosphere","image":"","options":["(iv) → (ii) → (i) → (iii)","(ii) → (i) → (iv) → (iii)","(i) → (ii) → (iv) → (iii)","(ii) → (iv) → (i) → (iii)"],"optionsInImage":false,"answer":["4"],"explanation":"Step 1 (ii): CFCs are first released in the lower atmosphere, for example from refrigerants.\nStep 2 (iv): They move upward and reach the stratosphere.\nStep 3 (i): In the stratosphere, UV rays act on them and release Cl atoms.\nStep 4 (iii): Cl atoms catalytically degrade O$_3$ to O$_2$.\nOption (2) is wrong because the Cl release by UV happens in the stratosphere, not before CFCs move up.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-052","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":52,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which one of the following statements about the greenhouse effect is correct?","image":"","options":["Clouds and atmospheric gases reflect roughly one-fourth of the incoming solar radiation","The Earth's surface re-emits absorbed solar energy mainly as ultraviolet radiation","Greenhouse gases warm the Earth mainly by absorbing incoming visible sunlight before it reaches the ground","Global warming is mainly a result of the thinning of the stratospheric ozone layer"],"optionsInImage":false,"answer":["1"],"explanation":"(1) Correct: clouds and gases reflect about one-fourth of the incoming solar radiation and absorb some of it. Roughly half reaches the surface and heats it.\n(2) Incorrect: the surface re-emits heat as infrared radiation, not UV.\n(3) Incorrect: greenhouse gases trap the outgoing infrared radiation. They are largely transparent to incoming visible light.\n(4) Incorrect: ozone depletion is a separate problem. Global warming comes from rising levels of greenhouse gases.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-053","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":53,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to NCERT, by about how much has the average temperature of the Earth increased during the past century?","image":"","options":["0.06°C","0.6°C","6°C","1.6°C"],"optionsInImage":false,"answer":["2"],"explanation":"The rising levels of greenhouse gases have raised the Earth's average temperature by about 0.6°C over the last century.\nMost of this rise took place in the last three decades.\nThe options 0.06°C and 6°C are off by a factor of ten in each direction.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-054","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":54,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which one of the following statements regarding the greenhouse effect and global warming is incorrect?","image":"","options":["Without the greenhouse effect, the average temperature at the earth's surface would be about –18°C instead of the present 15°C.","Earth's temperature rose by about 0.6°C during the past century, most of it during the last three decades.","Rising temperature may cause melting of polar ice caps and Himalayan snow caps, raising sea level and submerging coastal areas.","Among greenhouse gases, nitrous oxide makes the second largest contribution to global warming after carbon dioxide."],"optionsInImage":false,"answer":["4"],"explanation":"(1) Correct: the natural greenhouse effect keeps the average surface temperature near 15°C instead of –18°C.\n(2) Correct: NCERT reports a rise of about 0.6°C, mostly in the last three decades.\n(3) Correct: these are the predicted effects of global warming.\n(4) Incorrect: the relative contributions are $CO_2$ 60%, $CH_4$ 20%, CFCs 14% and $N_2O$ 6%. Methane is second; nitrous oxide is the smallest.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-055","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":55,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I (pollutant) with List-II (its fate in the pollution-control device):\nList-I\nA. Unburnt hydrocarbons\nB. Carbon monoxide\nC. Nitric oxide\nD. Particulate matter in thermal plant exhaust\nList-II\ni. Converted to nitrogen gas\nii. Converted to carbon dioxide and water\niii. Collected in an electrostatic precipitator\niv. Converted to carbon dioxide","image":"","options":["A-iv, B-ii, C-i, D-iii","A-ii, B-iv, C-iii, D-i","A-ii, B-iv, C-i, D-iii","A-i, B-iv, C-ii, D-iii"],"optionsInImage":false,"answer":["3"],"explanation":"A-ii: In a catalytic converter, unburnt hydrocarbons are converted to CO$_2$ and H$_2$O.\nB-iv: Carbon monoxide is oxidised to CO$_2$.\nC-i: Nitric oxide is changed to nitrogen gas.\nD-iii: Particulate matter from smokestacks is removed by an electrostatic precipitator.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-056","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":56,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Domestic sewage contains suspended solids, colloidal material and dissolved materials. Which of the following belongs to the colloidal fraction?","image":"","options":["Sand, silt and clay","Nitrate and phosphate ions","Faecal matter, bacteria, and cloth and paper fibres","Sodium and calcium ions"],"optionsInImage":false,"answer":["3"],"explanation":"Suspended solids are sand, silt and clay.\nColloidal material is faecal matter, bacteria, and cloth and paper fibres.\nDissolved materials are nutrients such as nitrate, ammonia and phosphate, along with ions like sodium and calcium.\nOptions (2) and (4) are dissolved materials, and option (1) is suspended solids.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-057","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":57,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements about the working of a catalytic converter is INCORRECT?","image":"","options":["Unburnt hydrocarbons are converted into carbon dioxide and water","Carbon monoxide is converted into carbon dioxide","Nitric oxide is converted into nitrogen gas","Carbon monoxide and nitric oxide are converted into methane and ammonia"],"optionsInImage":false,"answer":["4"],"explanation":"(1) Correct: unburnt hydrocarbons are converted to $CO_2$ and $H_2O$.\n(2) Correct: CO is converted to $CO_2$.\n(3) Correct: nitric oxide (NO) is converted to $N_2$ gas.\n(4) Incorrect: the converter does not produce methane or ammonia. The products are $CO_2$ and $N_2$, which are far less harmful.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-058","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":58,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): The greenhouse effect is a naturally occurring phenomenon that is essential for life on Earth.\nReason (R): Atmospheric gases such as CO2 and CH4 absorb the infrared radiation re-emitted by the Earth's surface and radiate part of it back, keeping the average temperature near 15°C.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true. The natural greenhouse effect keeps the Earth habitable; without it the average temperature would be about -18°C.\nR is true. Greenhouse gases trap the re-emitted infrared radiation and keep the average temperature near 15°C.\nR explains why the effect is essential, so it is the correct explanation of A.\nOnly the enhanced greenhouse effect, caused by rising gas levels, leads to global warming.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-059","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":59,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In an aquatic food chain, DDT is present at 0.003 ppb in the water and reaches 25 ppm in fish-eating birds. By roughly what factor has DDT been magnified from water to these birds? ($1\\ ppm = 1000\\ ppb$)","image":"","options":["$8.3\\times10^{2}$","$8.3\\times10^{3}$","$8.3\\times10^{6}$","$8.3\\times10^{9}$"],"optionsInImage":false,"answer":["3"],"explanation":"Given: DDT in water = 0.003 ppb; DDT in birds = 25 ppm. \nConvert to the same unit: 25 ppm = 25 × 1000 = 25000 ppb. \nFormula: magnification factor = concentration in birds ÷ concentration in water. \nSubstituting: 25000 ÷ 0.003 ≈ $8.3\\times10^{6}$. \nIf you forget to convert ppm to ppb, you get the wrong answer $8.3\\times10^{3}$. \nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-060","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":60,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements are correct?\n(i) Ozone present in the troposphere is harmful to plants and animals.\n(ii) In the stratosphere, ozone is continuously formed by the action of UV rays on molecular oxygen.\n(iii) The Montreal Protocol to control emission of ozone-depleting substances was signed in 1987.\n(iv) Chlorine atoms are released from CFCs when visible light acts on them in the troposphere.\n(v) Ozone depletion is particularly marked over the Arctic region, forming the ozone hole.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: tropospheric ozone is 'bad' ozone and harms plants and animals.\n(ii) Correct: UV rays split O2, and the products form O3. Ozone is also degraded back to O2, keeping a balance.\n(iii) Correct: the protocol was signed at Montreal, Canada, in 1987 and came into effect in 1989.\n(iv) Incorrect: Cl is released when UV rays act on CFCs in the stratosphere, not visible light in the troposphere.\n(v) Incorrect: the ozone hole is over the Antarctic region.\nSo three statements are correct.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-061","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":61,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are effects of increased UV-B exposure on humans, as described in NCERT?\n(i) Mutation due to DNA damage\n(ii) Ageing of skin\n(iii) Cataract\n(iv) Snow-blindness\n(v) Minamata disease\n(vi) Blue baby syndrome","image":"","options":["Three","Five","Four","Six"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: UV-B damages DNA, and mutation may occur.\n(ii) Correct: UV-B causes ageing of skin.\n(iii) Correct: high doses of UV-B can cause cataract.\n(iv) Correct: snow-blindness is inflammation of the cornea caused by UV-B.\n(v) Incorrect: Minamata disease is caused by mercury poisoning.\n(vi) Incorrect: blue baby syndrome is caused by excess nitrate in drinking water.\nSo four of the six are UV-B effects.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-062","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":62,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): In the absence of the greenhouse effect, the average temperature at the Earth's surface would be well below the freezing point of water.\nReason (R): Greenhouse gases absorb most of the incoming ultraviolet radiation from the Sun before it reaches the Earth's surface.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"A is true: without the greenhouse effect, the average temperature would be about -18°C instead of about 15°C.\nR is false: greenhouse gases warm the Earth by absorbing the infrared radiation that the heated surface emits, and re-radiating part of it back towards the surface.\nAbsorbing incoming UV radiation is the role of stratospheric ozone, not the mechanism of the greenhouse effect.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-063","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":63,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\n(A) Electrostatic precipitator\n(B) Scrubber\n(C) Catalytic converter\n(D) PM 2.5\nList-II\n(i) Can be inhaled deep into the lungs\n(ii) Changes nitric oxide into nitrogen gas\n(iii) Spray of water or lime removes SO$_2$\n(iv) Corona releases electrons that charge dust particles","image":"","options":["A-iii, B-iv, C-ii, D-i","A-iv, B-iii, C-i, D-ii","A-ii, B-iii, C-iv, D-i","A-iv, B-iii, C-ii, D-i"],"optionsInImage":false,"answer":["4"],"explanation":"A-iv: In an electrostatic precipitator, high-voltage electrode wires produce a corona. The released electrons give dust particles a charge.\nB-iii: A scrubber removes SO$_2$ using a water or lime spray.\nC-ii: A catalytic converter changes nitric oxide into nitrogen gas.\nD-i: Fine particles of PM 2.5 can be breathed deep into the lungs.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-064","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":64,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Sanitary landfills are not considered a lasting solution for the disposal of solid wastes in metro cities.\nReason (R): In a sanitary landfill, wastes are dumped in a depression or trench after compaction and covered with dirt every day.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["2"],"explanation":"A is true. NCERT says landfills are not really a solution because garbage generation, especially in metros, has risen so much that these sites are filling up. Chemicals can also seep out and pollute underground water.\nR is true. It correctly describes how a sanitary landfill works.\nHowever, R only describes the method. It does not explain why landfills fail, which is lack of space and seepage.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-065","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":65,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements are correct?\n(i) At Arcata, the wastewater was first given conventional sedimentation, filtering and chlorine treatment.\n(ii) The Arcata system used a series of six connected marshes spread over about 60 hectares.\n(iii) Conventional sedimentation and chlorination alone remove dissolved heavy metals completely from sewage.\n(iv) Ecosan toilets flush human excreta with water to produce biogas.\n(v) Using ecosan compost can reduce the need for chemical fertilisers.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: conventional treatment was the first stage at Arcata. \n(ii) Correct: six connected marshes covering about 60 ha were used. \n(iii) Incorrect: dissolved heavy metals remained after conventional treatment, and that is why the marshes were needed. \n(iv) Incorrect: ecosan uses dry composting toilets, with no water flushing. \n(v) Correct: the composted excreta serves as a natural fertiliser. \nSo 3 statements are correct. \nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-066","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":66,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements about polyblend are correct?\n(i) It was developed by Ahmed Khan, a plastic sack manufacturer of Bangalore.\n(ii) Any plastic film waste can serve as its raw material.\n(iii) Blending it with bitumen reduces the water-repellent property of bitumen.\n(iv) Roads laid with the polyblend–bitumen blend lasted about three times longer.\n(v) It was tested in collaboration with R.V. College of Engineering and the Bangalore City Corporation.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: Ahmed Khan was a plastic sack manufacturer in Bangalore.\n(ii) Correct: the raw material is any plastic film waste.\n(iii) Incorrect: the blend enhanced the water-repellent property of bitumen.\n(iv) Correct: road life increased by a factor of three.\n(v) Correct: Khan worked with R.V. College of Engineering and the Bangalore City Corporation.\nFour statements are correct.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-067","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":67,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: The National Forest Policy (1988) of India recommended 33% forest cover for the plains and 67% for the hills.\nStatement II: India's forest cover declined from about 30% at the beginning of the twentieth century to about 19.4% by its end.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["1"],"explanation":"Statement I is correct. The 1988 policy set 33% cover for plains and 67% for hills. Hills need more cover because they are prone to soil erosion and landslides.\nStatement II is correct. NCERT cites a fall from about 30% to 19.4% during the twentieth century, an example of deforestation.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-068","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":68,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In the Delhi case study of vehicular air pollution, the Supreme Court directed the government to switch the entire public transport fleet (buses) from diesel to CNG. By the end of which year was this switch to be completed?","image":"","options":["1997","2002","2005","2010"],"optionsInImage":false,"answer":["2"],"explanation":"In the 1990s Delhi ranked fourth among the 41 most polluted cities of the world.\nResponding to a public interest case, the Supreme Court directed the government to take several measures. One was switching all public transport buses from diesel to CNG by the end of 2002.\n1997–2005 is the period over which CO2 and SO2 levels in Delhi were later found to have fallen. 2005 and 2010 relate to the Bharat Stage norm timelines.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-069","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":69,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Dobson units (DU) are used to express which of the following?","image":"","options":["Concentration of chlorofluorocarbons in the troposphere","Thickness of ozone in a column of air from the ground to the top of the atmosphere","Oxygen content of air at sea level","Intensity of UV-B radiation reaching the Earth's surface"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT fact: the thickness of ozone in a column of air from the ground to the top of the atmosphere is measured in Dobson units.\nIt is not a measure of oxygen content. This is a common confusion because ozone is a form of oxygen.\nIt does not measure CFC levels or UV intensity either.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-070","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":70,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The Chipko movement, in which local women hugged trees to protect them from the axes of contractors, began in:","image":"","options":["Khejarli village, Rajasthan, in 1731","Garhwal Himalayas, in 1974","North-eastern states, in the 1980s","Western Ghats, in 1988"],"optionsInImage":false,"answer":["2"],"explanation":"The Chipko movement started in 1974 in the Garhwal Himalayas.\nLocal women hugged trees to stop contractors from cutting them.\nKhejarli in 1731 is the Bishnoi sacrifice led by Amrita Devi, a different event.\nThe 1980s is when Joint Forest Management was introduced, and 1988 is the year of the National Forest Policy.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-071","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":71,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Ramesh Chandra Dagar\nB. Chernobyl\nC. Excess fertiliser run-off into lakes\nD. Shielded containers in rocks about 500 m deep\nList-II\n(i) Eutrophication\n(ii) Disposal of pre-treated nuclear waste\n(iii) Integrated organic farming\n(iv) Accidental leakage of radioactive material","image":"","options":["A-(iii), B-(ii), C-(i), D-(iv)","A-(i), B-(iv), C-(iii), D-(ii)","A-(iii), B-(iv), C-(i), D-(ii)","A-(iv), B-(iii), C-(ii), D-(i)"],"optionsInImage":false,"answer":["3"],"explanation":"A: Dagar practises integrated organic farming in Sonipat, so A-(iii).\nB: Chernobyl, like Three Mile Island, was an accidental leakage of radioactive material, so B-(iv).\nC: Nutrient-rich fertiliser run-off causes eutrophication, so C-(i).\nD: Shielded containers buried in rocks about 500 m deep is the recommended disposal of pre-treated nuclear waste, so D-(ii).\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-072","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":72,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are given in NCERT as reasons why CNG is better than diesel as a vehicle fuel?\n(i) It burns most efficiently, leaving very little unburnt.\n(ii) It is cheaper than petrol or diesel.\n(iii) It cannot be siphoned off by thieves or adulterated like petrol or diesel.\n(iv) Laying pipelines for its distribution is easy and its supply is always uninterrupted.\n(v) Its main constituent is propane, which releases no carbon dioxide on burning.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: CNG burns most efficiently, so very little of it is left unburnt.\n(ii) Correct: CNG is cheaper than petrol or diesel.\n(iii) Correct: CNG cannot be siphoned off or adulterated.\n(iv) Incorrect: the main problem in switching to CNG is the difficulty of laying pipelines and ensuring uninterrupted supply.\n(v) Incorrect: CNG is mainly methane, not propane, and burning it does produce CO2.\nSo three statements are correct.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-073","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":73,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): The concentration of DDT in fish-eating birds is much higher than in the small fish they feed on.\nReason (R): DDT is quickly metabolised and excreted by organisms at each trophic level.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"A is true. In biomagnification, the concentration of DDT rises at each trophic level. Small fish carry about 0.5 ppm, while fish-eating birds carry about 25 ppm. \nR is false. DDT builds up precisely because an organism cannot metabolise or excrete it. It stays in the body and is passed to the next trophic level. \nIf DDT were quickly excreted, biomagnification would not happen. \nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-074","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":74,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are described in NCERT as consequences of global warming?\n(i) Odd climatic changes such as the El Niño effect\n(ii) Melting of polar ice caps and Himalayan snow caps\n(iii) Rise in sea level that can submerge coastal areas\n(iv) Snow-blindness caused by high doses of radiation\n(v) Formation of the ozone hole over Antarctica","image":"","options":["Two","Three","Four","Five"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: global warming causes odd climatic changes such as El Niño.\n(ii) Correct: it melts polar ice caps and Himalayan snow caps.\n(iii) Correct: the melting raises sea level and can submerge coastal areas.\n(iv) Incorrect: snow-blindness is caused by high doses of UV-B radiation and is linked to ozone depletion, not to warming.\n(v) Incorrect: the ozone hole results from CFCs destroying stratospheric ozone.\nThree statements are correct.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-075","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":75,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are components of the chain of mutually supporting processes in Ramesh Chandra Dagar's integrated organic farm?\nBee-keeping; Dairy management; Water harvesting; Composting; Application of chemical fertilisers; Burning of crop residue for disposal","image":"","options":["Three","Four","Five","Six"],"optionsInImage":false,"answer":["2"],"explanation":"Dagar links bee-keeping, dairy management, water harvesting, composting and agriculture in one chain of processes.\nBee-keeping, dairy management, water harvesting and composting from the list are all part of it, which makes four.\nChemical fertilisers are not used, because cattle dung serves as manure.\nCrop residue is not burnt. It is composted or used to generate natural gas, in keeping with the zero-waste idea.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-076","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":76,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Slash and burn agriculture was practised for a long time without serious damage, but it has now become a major cause of deforestation. What is the main reason for this change?","image":"","options":["Farmers have stopped burning the plant remains and leave them to rot","The ash produced today is less fertile because of acid rain","Growing population and repeated cultivation have removed the long recovery period the land needed","The practice has shifted from the north-eastern states to the plains"],"optionsInImage":false,"answer":["3"],"explanation":"In the past, farmers left a cultivated patch and gave it enough time to recover before returning to it.\nWith a larger population, the same land is now cultivated again and again.\nThis removes the recovery phase, so the forest cannot regenerate and deforestation follows.\nThe other options are not reasons given in NCERT. Farmers still burn the remains, and the ash is still used as fertiliser.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-077","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":77,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"A graph shows dissolved oxygen (DO) and biochemical oxygen demand (BOD) of a river plotted against distance from the point where untreated sewage enters it.\nStatement I: In the stretch just downstream of the sewage discharge point, DO falls sharply while BOD rises.\nStatement II: A higher BOD value indicates a lower polluting potential of the water.","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["2"],"explanation":"Statement I is correct. Sewage adds biodegradable organic matter. Microorganisms decomposing it use up oxygen, so DO drops and BOD rises near the outfall. Further downstream, as the organic matter is decomposed, DO recovers.\nStatement II is incorrect. BOD measures the amount of biodegradable organic matter in the water. A higher BOD therefore means a greater polluting potential, not a lower one.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-078","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":78,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The integrated wastewater treatment project at Arcata, California, which uses a series of natural marshes, is looked after and safeguarded mainly by:","image":"","options":["The Central Pollution Control Board","A citizens' group called Friends of the Arcata Marsh (FOAM)","The California Department of Fisheries","A private sewage treatment company"],"optionsInImage":false,"answer":["2"],"explanation":"Townspeople of Arcata worked with biologists from Humboldt State University to build a wastewater treatment system that relies on natural marshes. \nA citizens' group, Friends of the Arcata Marsh (FOAM), is responsible for the upkeep and protection of the project. \nThe CPCB is an Indian body and has no role in a Californian town's project. \nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-079","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":79,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: In the Arcata wastewater project, conventional sedimentation, filtering and chlorine treatment removed almost all dangerous pollutants, including dissolved heavy metals.\nStatement II: Biologists developed a series of six connected marshes over about 60 hectares, seeded with suitable plants, algae, fungi and bacteria that neutralise, absorb and assimilate pollutants.","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["3"],"explanation":"Statement I is incorrect. After the conventional sedimentation, filtering and chlorination stage, dangerous pollutants such as dissolved heavy metals still remained. \nStatement II is correct. To remove these, six connected marshes covering about 60 ha were seeded with plants, algae, fungi and bacteria. \nAs water flows through the marshes it is purified naturally, and the marshes also became a biodiversity sanctuary. \nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-080","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":80,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Suspended solids\nB. Colloidal material\nC. Dissolved materials\nD. Biochemical oxygen demand\nList-II\ni. Nitrate, ammonia, phosphate, sodium, calcium\nii. Sand, silt and clay\niii. Faecal matter, bacteria, cloth and paper fibres\niv. Measure of the organic matter load of water\nChoose the correct option.","image":"","options":["A-iii, B-ii, C-i, D-iv","A-ii, B-iii, C-i, D-iv","A-ii, B-i, C-iii, D-iv","A-iv, B-iii, C-i, D-ii"],"optionsInImage":false,"answer":["2"],"explanation":"A-ii: Suspended solids are sand, silt and clay.\nB-iii: Colloidal material includes faecal matter, bacteria, and cloth and paper fibres.\nC-i: Dissolved materials are nutrients such as nitrate, ammonia and phosphate, along with sodium and calcium.\nD-iv: BOD is a measure of the organic matter present in water.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-081","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":81,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Under the directives of the Supreme Court, Delhi converted its entire fleet of public transport buses from diesel to CNG. By the end of which year was this conversion completed?","image":"","options":["1997","2002","2005","2010"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT states that all the buses of Delhi were converted to run on CNG by the end of 2002.\n1997 and 2005 are the two ends of the period over which a fall in $CO_2$ and $SO_2$ levels was estimated, so they are tempting but wrong.\n2010 is unrelated to the CNG switch.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-082","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":82,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to NCERT, an electrostatic precipitator fitted to the exhaust of a thermal power plant can remove about what fraction of the particulate matter?","image":"","options":["About 50 per cent","About 75 per cent","Over 99 per cent","About 90 per cent"],"optionsInImage":false,"answer":["3"],"explanation":"An electrostatic precipitator gives dust particles an electric charge, and grounded plates then collect them.\nNCERT states that it can remove over 99 per cent of the particulate matter in the exhaust of a thermal power plant.\nThe lower figures understate its efficiency. Its real weakness is very fine particles, not overall removal.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-083","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":83,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Consider the following statements:\n(i) In 1731, the wood the King of Jodhpur wanted for building a new palace led to the sacrifice of Amrita Devi, her three daughters and hundreds of other Bishnois.\n(ii) The Amrita Devi Bishnoi Wildlife Protection Award is given to individuals or communities from rural areas who show extraordinary courage and dedication in protecting wildlife.\n(iii) Under Joint Forest Management, local communities help protect and manage forests and in return receive benefits of forest products such as fruits, gum, rubber and medicine.\n(iv) Joint Forest Management transferred complete ownership of forests to the local communities.\nWhich of the above statements are correct?","image":"","options":["(i) and (iv) only","(i), (ii) and (iii) only","(ii) and (iii) only","(i), (ii), (iii) and (iv)"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: the King of Jodhpur's ministers went to cut trees near a Bishnoi village. Amrita Devi hugged a tree and was killed along with her three daughters and hundreds of Bishnois.\n(ii) Correct: this award, instituted by the Government of India, honours rural individuals or communities who protect wildlife.\n(iii) Correct: under JFM, communities protect forests and in return share in forest products.\n(iv) Incorrect: JFM is a partnership between the government and communities, not a transfer of ownership.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-084","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":84,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In the context of industrial wastewater, which of the following correctly defines heavy metals such as mercury, cadmium, copper and lead?","image":"","options":["Elements with a density greater than $5\\ g\\ cm^{-3}$","Elements with an atomic number greater than 92","Any element that is radioactive","Elements with a density less than $1\\ g\\ cm^{-3}$"],"optionsInImage":false,"answer":["1"],"explanation":"NCERT defines heavy metals as elements whose density is greater than $5\\ g\\ cm^{-3}$. \nMercury, cadmium, copper and lead are examples found in wastewater from industries such as petroleum, paper manufacturing, metal extraction and chemical manufacturing. \nAtomic number above 92 describes transuranic elements, not heavy metals. \nRadioactivity is not part of the definition, since copper and lead (as commonly used) are not radioactive. \nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-085","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":85,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: According to the Central Pollution Control Board, particulate matter 2.5 $\\mu$m or less in diameter causes the greatest harm to human health.\nStatement II: A scrubber removes particulate matter from exhaust by collecting negatively charged dust particles on grounded collecting plates.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Statement I is correct. CPCB identifies PM 2.5 as most harmful. These fine particles reach deep into the lungs and cause breathing problems, irritation, inflammation and lung damage.\nStatement II is incorrect. Charging dust particles and collecting them on grounded plates is how an electrostatic precipitator works.\nA scrubber instead sprays water or lime to remove gases such as $SO_2$.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-086","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":86,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which aquatic weed, introduced into India for its lovely flowers and leaf shape, is called the 'Terror of Bengal'?","image":"","options":["Azolla","Eichhornia crassipes (water hyacinth)","Wolffia","Trapa (water chestnut)"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT describes Eichhornia crassipes (water hyacinth) as the world's most problematic aquatic weed and calls it the 'Terror of Bengal'.\nIt was brought in for its attractive flowers and leaves. It grows abundantly in eutrophic water bodies and upsets ecosystem dynamics.\nAzolla is a useful biofertiliser, not a nuisance weed.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-087","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":87,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In an aquatic food chain shown in NCERT, the DDT concentration is 0.003 ppb in the water and 25 ppm in fish-eating birds. Roughly how many times more concentrated is DDT in the birds than in the water? What effect does this level of DDT have on the birds?","image":"","options":["About $8.3 \\times 10^{3}$ times; it causes thickening of eggshells","About $8.3 \\times 10^{6}$ times; it disturbs calcium metabolism, causing thinning of eggshells and their premature breaking","About $8.3 \\times 10^{9}$ times; it disturbs calcium metabolism, causing thinning of eggshells","About $8.3 \\times 10^{6}$ times; it causes algal blooms in the birds' habitat"],"optionsInImage":false,"answer":["2"],"explanation":"Step 1: Bring both values to the same unit. Since 1 ppm = 1000 ppb, 0.003 ppb = $3 \\times 10^{-6}$ ppm. \nStep 2: Divide the two concentrations: $\\frac{25}{3 \\times 10^{-6}} \\approx 8.3 \\times 10^{6}$. \nStep 3: High DDT disturbs calcium metabolism in birds. Their eggshells become thin and break prematurely, which leads to a decline in bird populations. \nOption (1) uses $8.3 \\times 10^{3}$, which comes from wrongly treating ppb as ppm. \nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-088","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":88,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The Chipko movement, in which local women hugged trees to protect them from contractors' axes, began in 1974 in which region?","image":"","options":["Western Ghats of Karnataka","Thar desert near Jodhpur","Garhwal Himalayas","Khasi hills of Meghalaya"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT describes the Chipko movement of 1974 in the Garhwal Himalayas.\nLocal women embraced trees so that contractors could not cut them.\nThe Jodhpur region in Rajasthan is linked with the Bishnoi sacrifice of 1731, not with Chipko.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-089","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":89,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which feature correctly describes a sanitary landfill?","image":"","options":["Wastes are burnt in the open until only ash remains","Wastes are compacted, dumped in a trench or depression and covered with dirt every day","Wastes are dumped directly into rivers so that flowing water dilutes them","Wastes are left uncovered so that they can decompose faster in air"],"optionsInImage":false,"answer":["2"],"explanation":"Sanitary landfills replaced open-burning dumps.\nIn a sanitary landfill, wastes are compacted, dumped in a depression or trench, and covered with dirt every day.\nOpen burning describes open dumps, not landfills. Leaving wastes uncovered is also a feature of open dumps.\nDumping into rivers is water pollution, not a disposal method.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-090","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":90,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"A diagram of an electrostatic precipitator shows thin electrode wires at the centre and flat collecting plates on either side, with dusty exhaust flowing between them. Which description of its working is correct?","image":"","options":["The collecting plates emit electrons that give dust particles a positive charge, and the particles then move towards the wires.","Wires kept at several thousand volts produce a corona that releases electrons. The electrons attach to dust particles, giving them a net negative charge, and the grounded collecting plates attract them.","The corona releases protons that make dust particles positive, and the particles are repelled onto the plates by a fast air stream.","The wires give dust particles a negative charge, and negatively charged collecting plates attract them; a high air velocity between the plates helps the dust settle."],"optionsInImage":false,"answer":["2"],"explanation":"The electrode wires are kept at several thousand volts, producing a corona that releases electrons.\nThese electrons attach to dust particles and give them a net negative charge.\nThe collecting plates are grounded, so they attract the charged particles.\nThe air must move slowly between the plates so the dust can fall. This rules out option (4), which wrongly calls for high air velocity and negatively charged plates.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-091","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":91,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: In India, the Air (Prevention and Control of Pollution) Act came into force in 1981.\nStatement II: Noise was listed as an air pollutant in the Act right from the time it was first enacted.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is incorrect but Statement II is correct","Statement I is correct but Statement II is incorrect"],"optionsInImage":false,"answer":["4"],"explanation":"Statement I is correct. The Air (Prevention and Control of Pollution) Act came into force in 1981.\nStatement II is incorrect. Noise was not in the original Act; it was added as an air pollutant by an amendment in 1987.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-092","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":92,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): A high BOD value of a water body indicates that it is only slightly polluted by organic matter.\nReason (R): BOD measures the oxygen that microorganisms would consume if all the biodegradable organic matter in one litre of water were oxidised.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["4"],"explanation":"R is true. This is the NCERT definition of biochemical oxygen demand (BOD).\nA is false. More organic matter means more oxygen is needed to break it down, so BOD rises.\nA high BOD therefore signals greater polluting potential, not slight pollution.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-093","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":93,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The following events occur during the natural ageing (eutrophication) of a lake:\nP. Silt and organic debris pile up, and the lake becomes shallower and warmer, so warm-water organisms replace cold-water ones.\nQ. The water is cold and clear and supports very little life.\nR. Large masses of floating plants form a bog, which finally turns into land.\nS. Streams bring in nitrogen and phosphorus, fertility rises, and organic remains begin to settle on the lake bottom.\nT. Marsh plants take root in the shallows and begin to fill the lake basin.\nWhich option gives the correct sequence?","image":"","options":["Q → P → S → T → R","S → Q → P → R → T","Q → S → T → P → R","Q → S → P → T → R"],"optionsInImage":false,"answer":["4"],"explanation":"Q: A young lake is cold and clear and holds little life.\nS: Nutrients from streams increase fertility, and organic remains begin to settle.\nP: Silt and debris build up over centuries, so the lake grows shallower and warmer, and warm-water organisms replace cold-water ones.\nT: Marsh plants root in the shallows and fill the basin.\nR: Floating plant masses form a bog, which finally becomes land.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-094","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":94,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Exhaust gases from an industry are passed through a spray of water or lime to remove sulphur dioxide. The device used is a:","image":"","options":["Catalytic converter","Scrubber","Electrostatic precipitator","Incinerator"],"optionsInImage":false,"answer":["2"],"explanation":"A scrubber removes gases like SO$_2$ by passing the exhaust through a spray of water or lime.\nAn electrostatic precipitator removes particulate matter, not gases.\nA catalytic converter treats vehicle exhaust. An incinerator burns waste.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-095","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":95,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which one of the following statements about nuclear energy and radioactive wastes is INCORRECT?","image":"","options":["Nuclear energy was initially hailed as a non-polluting way of generating electricity.","Accidental leakage and safe disposal of radioactive waste are the two serious inherent problems of nuclear energy.","Nuclear radiation is lethal at high doses, while at lower doses it causes various disorders.","Burying pre-treated nuclear waste in shielded containers deep within rocks has gained wide public acceptance."],"optionsInImage":false,"answer":["4"],"explanation":"(1) Correct: nuclear energy was first considered non-polluting.\n(2) Correct: NCERT names accidental leakage (Three Mile Island, Chernobyl) and safe waste disposal as the two inherent problems.\n(3) Correct: high doses are lethal, and lower doses cause disorders, most often cancer.\n(4) Incorrect: NCERT states that deep burial of pre-treated waste in shielded containers is meeting stiff opposition from the public.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-096","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":96,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: In slash and burn (jhum) agriculture, increasing population and repeated cultivation have removed the recovery phase of the land, and this has led to deforestation.\nStatement II: Reforestation needs trees to be planted by humans; a forest that was removed cannot be restored naturally.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Statement I is correct. In jhum, practised in the north-eastern states, trees are cut and burnt and the ash serves as fertiliser. Earlier, the land was left for several years to recover. Population pressure has removed this gap, which causes deforestation.\nStatement II is incorrect. Reforestation restores a forest that once existed. It can occur naturally, and humans can speed it up by planting trees while keeping the original biodiversity in mind.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-097","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":97,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to NCERT, noise is best defined as:","image":"","options":["Any sound with a frequency above 20,000 Hz","Undesired high level of sound","Sound produced only by industrial machinery","Any sound below 30 dB that disturbs sleep"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT defines noise as undesired high level of sound.\nTwo things matter: the sound is unwanted, and it is loud.\nA frequency above 20,000 Hz is ultrasound, which humans cannot hear, so (1) does not describe noise.\nNoise comes from many sources, especially transport, not only industry, so (3) is too narrow.\nA sound below 30 dB is very soft and is not 'high level', so (4) fails.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-098","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":98,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to the Euro II norms described under India's auto fuel policy, the permitted sulphur content in diesel and in petrol is, respectively:","image":"","options":["150 ppm and 350 ppm","50 ppm and 50 ppm","350 ppm and 150 ppm","500 ppm and 350 ppm"],"optionsInImage":false,"answer":["3"],"explanation":"Stricter fuel norms steadily lower the sulphur and aromatic hydrocarbon content of fuels.\nEuro II norms limit sulphur to 350 ppm in diesel and 150 ppm in petrol. Aromatic hydrocarbons are capped at 42% of the fuel.\nThe roadmap's later goal is 50 ppm sulphur in both fuels, with aromatics at 35%. That is why option (2) is the future target, not the Euro II limit.\nOption (1) reverses the two values.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-099","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":99,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements is incorrect?","image":"","options":["The Bishnois at Khejarli resisted the felling of trees ordered to obtain wood for a new palace for the king","The Amrita Devi Bishnoi Wildlife Protection Award honours individuals or communities from rural areas who show extraordinary courage in protecting wildlife","Under Joint Forest Management, local communities help protect and manage forests and in return receive forest products such as fruits, gum, rubber and medicine","Temperate forests have lost about 40% of their area, while tropical forests have lost only about 1%"],"optionsInImage":false,"answer":["4"],"explanation":"(1) Correct: the king's ministers wanted wood to build a new palace, and the Bishnois led by Amrita Devi resisted.\n(2) Correct: the Government of India instituted this award for rural individuals or communities.\n(3) Correct: JFM, introduced in the 1980s, shares forest products with local communities in return for their help.\n(4) Incorrect: the figures are reversed. About 40% of tropical forests have been lost, compared with only about 1% of temperate forests.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-100","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":100,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Just downstream of the point where sewage is discharged into a river, the dissolved oxygen of the water falls sharply.\nReason (R): Impurities make up only about 0.1 percent of domestic sewage.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["2"],"explanation":"A is true: microbes decomposing the biodegradable organic matter in sewage use up oxygen, so BOD rises and DO falls downstream.\nR is true: NCERT notes that sewage carries only about 0.1% impurities.\nHowever, the small percentage of impurities does not explain the fall in oxygen. The fall is caused by microbial decomposition, so R is not the explanation.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-101","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":101,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Consider the following impurities found in domestic sewage:\nnitrate, ammonia, silt, phosphate, bacteria, sodium, paper fibres, clay\nHow many of these belong to the dissolved materials category?","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT groups the impurities in domestic sewage into three categories.\nSuspended solids: sand, silt and clay. This category includes silt and clay from the list.\nColloidal material: faecal matter, bacteria, cloth and paper fibres. This category includes bacteria and paper fibres.\nDissolved materials: nitrate, ammonia, phosphate, sodium and calcium. This category includes nitrate, ammonia, phosphate and sodium.\nSo 4 items in the list are dissolved materials.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-102","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":102,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"High concentrations of DDT cause a decline in populations of fish-eating birds mainly because DDT:","image":"","options":["blocks oxygen transport by haemoglobin in birds","disturbs calcium metabolism, leading to thin eggshells that break prematurely","causes snow-blindness, so birds cannot locate prey","makes fish unpalatable, so birds starve"],"optionsInImage":false,"answer":["2"],"explanation":"According to NCERT, high DDT levels disturb calcium metabolism in birds. \nAs a result, eggshells become thin and break before hatching, so fewer young survive and bird populations decline. \nSnow-blindness is caused by UV-B radiation, not by DDT. \nCarbon monoxide, not DDT, is the pollutant that interferes with oxygen transport. \nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-103","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":103,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: Ozone present in the troposphere is called 'good' ozone because it shields living organisms from ultraviolet radiation.\nStatement II: DNA and proteins preferentially absorb UV rays, and the high energy of UV breaks chemical bonds within these molecules.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is incorrect but Statement II is correct","Statement I is correct but Statement II is incorrect"],"optionsInImage":false,"answer":["3"],"explanation":"Statement I is incorrect. Tropospheric (lower atmosphere) ozone is 'bad' ozone because it harms plants and animals. The 'good' ozone that absorbs UV is in the stratosphere.\nStatement II is correct. This is exactly why NCERT calls UV highly injurious: DNA and proteins absorb it, and its high energy breaks their chemical bonds.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-104","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":104,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which aquatic plant, which grows abundantly in eutrophic water bodies, is popularly called the 'Terror of Bengal'?","image":"","options":["Lantana camara","Parthenium hysterophorus","Eichhornia crassipes","Trapa natans"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT calls water hyacinth (Eichhornia crassipes) the world's most problematic aquatic weed and also the 'Terror of Bengal'.\nIt grows abundantly in eutrophic water bodies and disturbs the balance of the ecosystem.\nLantana and Parthenium are invasive weeds of land, not of water.\nTrapa (water chestnut) is a cultivated aquatic plant.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-105","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":105,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which one of the following statements about ozone depletion is correct?","image":"","options":["The ozone hole is most prominently formed over the Arctic region.","Chlorine atoms released from CFCs act catalytically in the stratosphere and are not consumed while degrading ozone.","The Montreal Protocol to control ozone-depleting substances was signed in 1997.","Ozone present in the troposphere shields living organisms from harmful UV-B radiation."],"optionsInImage":false,"answer":["2"],"explanation":"(1) Incorrect: the large ozone hole forms over Antarctica.\n(2) Correct: UV rays release Cl atoms from CFCs in the stratosphere. These Cl atoms convert ozone to oxygen and are not consumed, so a little CFC has a lasting effect.\n(3) Incorrect: the Montreal Protocol was signed in 1987 and came into effect in 1989.\n(4) Incorrect: tropospheric ozone is 'bad' ozone; the protective layer is in the stratosphere.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-106","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":106,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements are correct?\n(i) Noise of 150 dB or more, such as that of a jet plane taking off, may damage eardrums and permanently impair hearing.\n(ii) By the end of 2002, the entire public road transport of Delhi had been converted to run on CNG.\n(iii) Radioactive waste should be stored in suitably shielded containers buried within rocks about 500 m deep below the earth's surface.\n(iv) Eichhornia, called the 'Terror of Bengal', grows abundantly in eutrophic water bodies.\n(v) The Air (Prevention and Control of Pollution) Act was amended in 1981 to include noise as an air pollutant.\n(vi) Mixing polyblend with bitumen lowers the water-repellent property of bitumen.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: NCERT cites jet or rocket take-off noise of 150 dB or more.\n(ii) Correct: Delhi's switch to CNG was completed by end-2002.\n(iii) Correct: this is NCERT's recommended disposal method for radioactive waste.\n(iv) Correct: water hyacinth thrives in nutrient-rich water.\n(v) Incorrect: the Act was passed in 1981; noise was added in 1987.\n(vi) Incorrect: polyblend enhances water repellence and triples road life.\nCorrect statements = 4.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-107","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":107,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Consider the following statements about catalytic converters fitted in automobiles:\n(i) They contain expensive metals such as platinum-palladium and rhodium as catalysts.\n(ii) They convert carbon monoxide and nitric oxide into carbon dioxide and nitrogen gas respectively.\n(iii) They convert unburnt hydrocarbons into carbon monoxide and methane.\n(iv) Vehicles fitted with them must use leaded petrol, because lead activates the catalyst.\nWhich of the above statements are correct?","image":"","options":["(i) and (ii) only","(i), (ii) and (iii) only","(ii) and (iv) only","(i), (iii) and (iv) only"],"optionsInImage":false,"answer":["1"],"explanation":"(i) Correct: platinum-palladium and rhodium are the catalysts used.\n(ii) Correct: CO is oxidised to CO2, and nitric oxide is converted to N2.\n(iii) Incorrect: unburnt hydrocarbons are converted to carbon dioxide and water, not CO and methane.\n(iv) Incorrect: such vehicles must use unleaded petrol, because lead inactivates the catalyst. This is why unleaded petrol was introduced alongside catalytic converters.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-108","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":108,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements about stratospheric ozone is INCORRECT?","image":"","options":["Ozone is continuously formed by the action of UV rays on molecular oxygen and is also degraded into molecular oxygen in the stratosphere.","UV radiation of wavelengths shorter than UV-B is almost completely absorbed by the Earth's atmosphere, provided the ozone layer is intact.","The Montreal Protocol and later efforts laid down a single, identical roadmap for both developed and developing countries for reducing CFC emissions.","Enhanced degradation of ozone by CFCs has disturbed the balance between ozone production and ozone breakdown."],"optionsInImage":false,"answer":["3"],"explanation":"(1) Correct: UV acting on O$_2$ forms O$_3$, which is also broken back down to O$_2$, so there is a natural balance.\n(2) Correct: if the ozone layer is intact, UV of wavelengths shorter than UV-B is almost fully absorbed by the atmosphere.\n(3) Incorrect: the protocols laid down separate roadmaps for developed and developing countries.\n(4) Correct: CFCs speed up ozone degradation and so upset the balance.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-109","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":109,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The naturally occurring greenhouse effect keeps the average surface temperature of the Earth at about 15°C. What would the average surface temperature be if this effect were absent?","image":"","options":["0°C","-18°C","-40°C","5°C"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT fact: greenhouse gases trap heat near the Earth's surface and keep the average temperature at about 15°C.\nWithout the greenhouse effect, the average surface temperature would fall to about -18°C.\nThe Earth would then be far too cold for most life.\n0°C is a tempting option, but it is only the freezing point of water and is not the value given in NCERT.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-110","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":110,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Open-burning dumps\nB. Hospital wastes\nC. Polyblend–bitumen blend\nD. E-wastes from developed countries\nList-II\ni. Destroyed using incinerators\nii. Exported to developing countries for metal recovery\niii. Incomplete burning; breeding ground for rats and flies\niv. Better water repellence; road life increased about three times","image":"","options":["A-iii, B-i, C-iv, D-ii","A-i, B-iii, C-ii, D-iv","A-iii, B-iv, C-i, D-ii","A-ii, B-i, C-iv, D-iii"],"optionsInImage":false,"answer":["1"],"explanation":"A–iii: In open dumps, waste is generally not burnt completely, so the dumps breed rats and flies.\nB–i: Hospital wastes are hazardous and are disposed of in incinerators.\nC–iv: Polyblend improves bitumen's water-repellent property and raises road life by a factor of about three.\nD–ii: Over half of the e-waste of developed nations is exported to countries like China, India and Pakistan, where metals are recovered.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-111","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":111,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are greenhouse gases?\nCarbon dioxide, Methane, Nitrogen, Nitrous oxide, Chlorofluorocarbons, Argon","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"Greenhouse gases: carbon dioxide, methane, nitrous oxide and CFCs (water vapour is also one, but it is not listed).\nNitrogen and argon do not absorb and re-emit infrared radiation, so they are not greenhouse gases.\nTotal = 4.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-112","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":112,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Catalytic converters fitted in automobiles contain which of the following expensive metals as catalysts?","image":"","options":["Iron and nickel","Platinum-palladium and rhodium","Copper and zinc","Lead and mercury"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT states that catalytic converters contain expensive metals, namely platinum-palladium and rhodium, as catalysts.\nIron and nickel are catalysts in other industrial processes, not in vehicle converters.\nLead actually poisons the catalyst.\nMercury is a toxic pollutant, not a catalyst.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-113","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":113,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II:\nList-I\n(A) Dobson unit\n(B) CFCs\n(C) Cornea\n(D) Montreal, Canada\nList-II\n(i) Absorbs UV-B radiation in the human eye\n(ii) Widely used as refrigerants\n(iii) Treaty on ozone-depleting substances signed here\n(iv) Thickness of ozone in an air column\nChoose the correct option:","image":"","options":["A-(iv), B-(i), C-(ii), D-(iii)","A-(iv), B-(ii), C-(i), D-(iii)","A-(ii), B-(iv), C-(i), D-(iii)","A-(iii), B-(ii), C-(i), D-(iv)"],"optionsInImage":false,"answer":["2"],"explanation":"A-(iv): The Dobson unit measures the thickness of ozone in a column of air.\nB-(ii): CFCs find wide use as refrigerants.\nC-(i): The cornea absorbs UV-B, and a high dose causes snow-blindness.\nD-(iii): The Montreal Protocol was signed at Montreal, Canada, in 1987.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-114","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":114,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are correct statements about a catalytic converter in a car exhaust system?\n(i) Unburnt hydrocarbons are converted into carbon dioxide and water.\n(ii) Carbon monoxide is converted into carbon dioxide.\n(iii) Nitric oxide is converted into ammonia.\n(iv) Nitric oxide is converted into nitrogen gas.\n(v) Rhodium is one of the catalysts used.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: unburnt hydrocarbons are converted into CO$_2$ and H$_2$O.\n(ii) Correct: CO is oxidised to CO$_2$.\n(iii) Incorrect: nitric oxide is not converted into ammonia.\n(iv) Correct: nitric oxide is changed to nitrogen gas.\n(v) Correct: rhodium is used along with platinum and palladium.\nSo four statements are correct.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-115","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":115,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"A metropolitan city closes its open-burning dumps and shifts entirely to sanitary landfills. Based on NCERT, which pair of problems would still remain?","image":"","options":["Incomplete burning of waste and breeding of rats and flies","Release of methyl isocyanate and accumulation of radioactive waste","Landfill sites getting filled up due to rising garbage, and chemicals seeping into groundwater","Biomagnification of DDT and depletion of the ozone layer"],"optionsInImage":false,"answer":["3"],"explanation":"Step 1: Landfills cover compacted waste with dirt daily, so incomplete burning and pests (option 1) are reduced.\nStep 2: NCERT says landfills are not a real solution in metros, because garbage generation has risen so much that the sites are getting filled.\nStep 3: Chemicals can also seep out of landfills and pollute underground water.\nStep 4: The other options are unrelated issues.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-116","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":116,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Mercury in water bodies\nB. Thermal wastewater from power plants\nC. FOAM\nD. Ecosan\nList-II\n(i) Dry composting toilets that recycle human excreta into fertiliser\n(ii) Biomagnification in aquatic food chains\n(iii) Citizens' group responsible for the upkeep of Arcata's marshes\n(iv) Elimination or reduction of organisms sensitive to high temperature","image":"","options":["A-(ii), B-(iv), C-(iii), D-(i)","A-(iv), B-(ii), C-(i), D-(iii)","A-(ii), B-(iii), C-(iv), D-(i)","A-(i), B-(iv), C-(iii), D-(ii)"],"optionsInImage":false,"answer":["1"],"explanation":"A-(ii): Like DDT, mercury undergoes biomagnification as it passes along aquatic food chains. \nB-(iv): Hot water released from electricity-generating units eliminates or reduces organisms that are sensitive to high temperature. \nC-(iii): Friends of the Arcata Marsh (FOAM) looks after and safeguards the marsh-based treatment system. \nD-(i): Ecosan uses dry composting toilets to turn human excreta into natural fertiliser. \nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-117","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":117,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: Delhi has more cars than the states of Gujarat and West Bengal put together.\nStatement II: The main problem in switching Delhi's buses to CNG was that CNG is costlier than diesel.","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["2"],"explanation":"Statement I is correct: NCERT notes that Delhi has more cars than Gujarat and West Bengal combined.\nStatement II is incorrect on two counts. CNG is cheaper than petrol or diesel. The main problem was laying down pipelines to the distribution points and keeping the supply uninterrupted.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-118","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":118,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following is NOT a noise-control measure suggested in NCERT?","image":"","options":["Declaring areas around hospitals and schools as horn-free zones","Muffling the noise produced by machines and vehicles","Raising the permissible sound limit of vehicle horns","Fixing a time after which loudspeakers cannot be played"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT suggests these ways to reduce noise: using sound-absorbent materials, muffling noise, making hospital and school zones horn-free, and fixing the time after which loudspeakers cannot be played.\nRaising the permitted loudness of horns would add to noise, not reduce it.\nSo option (3) is the only one that is not a control measure.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-119","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":119,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements are correct?\n(a) Even about 0.1 per cent impurities make domestic sewage unfit for human use.\n(b) Dissolved nutrients such as nitrates and phosphates are harder to remove from sewage than suspended solids.\n(c) A higher BOD of a water sample indicates a lower polluting potential.\n(d) Some bloom-forming algae are extremely toxic to humans and animals.\n(e) Cultural eutrophication, like natural eutrophication, takes thousands of years to age a lake.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"(a) Correct: NCERT states that 0.1% impurities make sewage unfit.\n(b) Correct: solids are relatively easy to remove, while dissolved salts and nutrients are the most difficult.\n(c) Incorrect: a higher BOD means more organic matter and therefore greater polluting potential.\n(d) Correct: some bloom-forming algae produce toxins harmful to humans and animals.\n(e) Incorrect: human effluents radically accelerate ageing, compressing what naturally takes thousands of years.\nThat gives 3 correct statements.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-120","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":120,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"'EcoSan' toilets, which are working in many areas of Kerala and Sri Lanka, are based on:","image":"","options":["flushing excreta into septic tanks with chlorination","dry composting of human excreta into a natural fertiliser","incinerating human waste to generate electricity","discharging excreta into constructed marshes"],"optionsInImage":false,"answer":["2"],"explanation":"Ecological sanitation (EcoSan) is a sustainable way of handling human excreta using dry composting toilets. \nThe excreta is recycled into a resource, a natural fertiliser, which reduces the need for chemical fertilisers. \nNCERT describes it as hygienic, efficient and cost-effective. \nMarsh-based treatment is the Arcata approach, not EcoSan. \nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-121","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":121,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In NCERT, heavy metals present in industrial wastewater are defined as elements whose density is greater than:","image":"","options":["$1\\ g/cm^3$","$2.5\\ g/cm^3$","$5\\ g/cm^3$","$10\\ g/cm^3$"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT says industrial wastewater from petroleum, paper, metal extraction and chemical industries often contains heavy metals. \nIt defines heavy metals as elements with density greater than $5\\ g/cm^3$, such as mercury, cadmium, copper and lead. \n$1\\ g/cm^3$ is roughly the density of water, so it is not the cut-off. \n$10\\ g/cm^3$ would wrongly exclude copper and cadmium, which NCERT lists as heavy metals. \nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-122","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":122,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Just downstream of the point where untreated sewage enters a river, the dissolved oxygen content of the water drops sharply.\nReason (R): Microorganisms that decompose the biodegradable organic matter in sewage consume a large amount of oxygen.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true. NCERT describes a sharp fall in dissolved oxygen (DO) downstream of a sewage discharge point. This fall kills fish and other aquatic animals.\nR is true. Microbes breaking down the large organic load of sewage use up oxygen, which is shown as a high BOD.\nThis oxygen consumption is exactly what causes the fall in DO, so R correctly explains A.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-123","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":123,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Ramesh Chandra Dagar, who practises integrated organic farming in Sonipat, created an organisation to spread information on this practice. Which organisation is it?","image":"","options":["Joint Forest Management Committee","Chipko Andolan Samiti","Haryana Kisan Welfare Club","Central Pollution Control Board"],"optionsInImage":false,"answer":["3"],"explanation":"Dagar founded the Haryana Kisan Welfare Club to share information on integrated organic farming and help other farmers adopt it.\nNCERT gives its membership as about 5000 farmers.\nJoint Forest Management involves local communities in protecting forests, which is unrelated.\nThe Chipko movement was a forest-protection movement.\nThe CPCB is a government regulatory body, not a farmers' club.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-124","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":124,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements about electronic wastes (e-wastes) are correct?\n(i) More than half of the e-wastes generated in the developed world are exported to developing countries such as China, India and Pakistan.\n(ii) Metals like copper, iron, silicon, nickel and gold are recovered from e-wastes during recycling.\n(iii) Recycling of e-wastes in developing countries is largely automated, so workers face little exposure to toxic substances.\n(iv) Eco-friendly recycling is regarded as the only real solution to the e-waste problem.\n(v) Irreparable computers and other electronic goods are mainly disposed of by composting.","image":"","options":["Two","Three","Four","Five"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: NCERT says over half of the developed world's e-waste goes to developing countries.\n(ii) Correct: copper, iron, silicon, nickel and gold are recovered during recycling.\n(iii) Incorrect: recycling there often involves manual work, which exposes workers to toxic substances.\n(iv) Correct: NCERT calls eco-friendly recycling the only solution.\n(v) Incorrect: e-wastes are buried in landfills or incinerated. They are not biodegradable, so they cannot be composted.\nSo three statements are correct.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-125","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":125,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements about air pollution are correct?\n(i) Air pollutants can reduce the growth and yield of crops.\n(ii) Air pollutants can cause premature death of plants.\n(iii) The severity of harm depends on the concentration of the pollutant, the duration of exposure and the organism.\n(iv) Smokestack exhaust contains only harmful gases; harmless gases such as nitrogen and oxygen are absent from it.\n(v) Fine particulates can cause inflammation and damage to the lungs and even premature death.","image":"","options":["Two","Three","Four","Five"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: crop growth and yield fall under air pollution.\n(ii) Correct: plants may die prematurely.\n(iii) Correct: NCERT names concentration, duration of exposure and the organism as the deciding factors.\n(iv) Incorrect: smokestacks release pollutants together with harmless gases like N$_2$ and O$_2$.\n(v) Correct: fine particulates irritate, inflame and damage the lungs.\nFour statements are correct.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-126","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":126,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Even a limited quantity of CFCs reaching the stratosphere has a permanent and continuing effect on ozone levels.\nReason (R): Chlorine atoms released from CFCs act as catalysts in ozone degradation and are not consumed in the reaction.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"UV rays act on CFCs in the stratosphere and release Cl atoms.\nCl degrades ozone to molecular oxygen. It acts only as a catalyst, so it is not used up and keeps destroying more ozone molecules. R is true.\nBecause Cl keeps acting, CFCs added to the stratosphere have a permanent and continuing effect. A is true.\nR directly explains A.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-127","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":127,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Hospital wastes contain disinfectants, other harmful chemicals and pathogenic micro-organisms. According to NCERT, which method is crucial for their disposal?","image":"","options":["Open dumping","Composting","Incineration","Discharge into sewers"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT describes hospital wastes as hazardous because they carry harmful chemicals and pathogens.\nIt states that incinerators are crucial for disposing of hospital waste, because burning at high temperature destroys the pathogens.\nOpen dumping and sewer discharge would spread infection.\nComposting suits only harmless biodegradable waste.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-128","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":128,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"An electrostatic precipitator fitted in the smokestack of a thermal power plant can remove roughly what fraction of the particulate matter in the exhaust?","image":"","options":["Less than 50 per cent","Over 99 per cent","About 70 per cent","About 85 per cent"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT describes the electrostatic precipitator as the most widely used device for removing particulates from thermal power plant exhaust.\nIt can remove over 99 per cent of the particulate matter.\nThe lower figures underestimate its efficiency. That high efficiency is why it is the preferred method for particulates.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-129","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":129,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Whatever amount of CFCs is released into the atmosphere has a permanent and continuing effect on the stratospheric ozone.\nReason (R): The chlorine atoms released from CFCs act as catalysts in the breakdown of ozone and are not consumed in the reaction.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"CFCs move up into the stratosphere. There, UV rays act on them and release Cl atoms.\nEach Cl atom degrades ozone to molecular oxygen. Because it acts only as a catalyst, it is not used up in the reaction. R is therefore true.\nSince the Cl atoms are not consumed, they keep destroying ozone molecule after molecule. This is exactly why NCERT says CFCs have permanent and continuing effects. A is true, and R explains it.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-130","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":130,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"A graph shows how dissolved oxygen (DO) and Biochemical Oxygen Demand (BOD) change in a river at points located progressively downstream of an outlet discharging untreated domestic sewage. Which description correctly matches the expected curves?","image":"","options":["DO falls sharply and then gradually recovers, while BOD rises sharply and then gradually declines","DO and BOD both fall sharply just after the outlet and then both rise together","DO rises sharply because algae are added with the sewage, while BOD stays constant","BOD falls sharply and then recovers, while DO remains unchanged along the river"],"optionsInImage":false,"answer":["1"],"explanation":"At the outlet, the large organic load raises BOD sharply.\nMicrobes decompose this load and use up oxygen, so DO dips steeply. Fish and other aquatic animals may die in this zone.\nFurther downstream, the organic matter gets used up, so BOD gradually declines.\nAs the oxygen demand falls, DO slowly recovers.\nThe two curves therefore mirror each other, which only option (1) describes.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-131","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":131,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In the aquatic food chain used by NCERT to show biomagnification of DDT, the water contains 0.003 ppb of DDT. Match each organism in List-I with its DDT concentration in List-II.\nList-I\nA. Zooplankton\nB. Small fish\nC. Large fish\nD. Fish-eating birds\nList-II\ni. 2 ppm\nii. 25 ppm\niii. 0.04 ppm\niv. 0.5 ppm","image":"","options":["A-iii, B-iv, C-i, D-ii","A-iv, B-iii, C-ii, D-i","A-iii, B-i, C-iv, D-ii","A-i, B-iv, C-iii, D-ii"],"optionsInImage":false,"answer":["1"],"explanation":"DDT concentration rises at every higher trophic level. \nZooplankton have the lowest value, 0.04 ppm (A-iii). \nSmall fish have 0.5 ppm (B-iv). \nLarge fish have 2 ppm (C-i). \nFish-eating birds, at the top of the chain, have the highest value, 25 ppm (D-ii). \nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-132","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":132,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Discharge of untreated domestic sewage into a river causes a sharp fall in dissolved oxygen just downstream of the outfall.\nReason (R): Microorganisms decomposing the biodegradable organic matter in sewage consume large amounts of oxygen.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true. Below the sewage outfall, dissolved oxygen (DO) drops steeply, which can kill fish.\nR is true. Sewage is mostly biodegradable organic matter, and the microbes breaking it down use up oxygen. This is measured as a high BOD.\nOxygen use by decomposers is exactly why DO falls, so R correctly explains A.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-133","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":133,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In Ramesh Chandra Dagar's integrated organic farm, chemical fertilisers are not needed for the crops mainly because:","image":"","options":["crop waste is burnt and the ash is spread in the fields","honey bees fix atmospheric nitrogen in the soil","harvested rainwater supplies all the minerals needed","cattle excreta (dung) from the dairy is used as manure"],"optionsInImage":false,"answer":["4"],"explanation":"Dagar's farm links dairy, bee-keeping, water harvesting, composting and agriculture.\nCattle dung from the dairy is used as manure, so chemical fertilisers are not required.\nCrop waste is composted, not burnt.\nBees pollinate flowers but do not fix nitrogen.\nRainwater is harvested for water, not as a mineral source.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-134","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":134,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): The concentration of a toxicant such as mercury or DDT increases at successive trophic levels of a food chain.\nReason (R): A toxicant accumulated by an organism cannot be metabolised or excreted, so it is passed on to the next higher trophic level.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true. This rise in concentration up the food chain is called biomagnification, and NCERT cites mercury and DDT as well-known examples. \nR is true. The toxicant is neither broken down nor excreted, so it stays in the body tissues. \nEach consumer eats many organisms from the level below and retains their load, so the toxicant concentrates upward. \nR therefore correctly explains A. \nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-135","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":135,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements are correct?\n(i) Heated wastewater may enhance the growth of plants and fish in extremely cold areas, but only after damaging the indigenous flora and fauna.\n(ii) In Arcata, chlorine treatment was the final step that removed dissolved heavy metals from the wastewater.\n(iii) Ecological sanitation converts human excreta into natural fertiliser and reduces the need for chemical fertilisers.\n(iv) Biomagnification is well documented for mercury and DDT.\n(v) Copper is not considered a heavy metal because its density is below $5\\ g/cm^3$.","image":"","options":["Two","Three","Four","Five"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: this is NCERT's description of thermal wastewater. \n(ii) Incorrect: dissolved heavy metals remained after chlorination and were removed by the marsh stage. \n(iii) Correct: EcoSan dry composting recycles excreta into natural fertiliser. \n(iv) Correct: NCERT names mercury and DDT as classic examples. \n(v) Incorrect: copper is listed as a heavy metal, and its density (about 8.9 $g/cm^3$) is above 5. \nSo three statements are correct. \nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-136","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":136,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"As described in NCERT, municipal solid wastes are best defined as:","image":"","options":["Wastes from homes, offices, stores, schools and hospitals that are collected and disposed of by the municipality","Only the industrial effluents released by factories into city drains","Only non-biodegradable wastes such as plastics and metals produced in cities","Agricultural residues such as crop stubble collected from farms near cities"],"optionsInImage":false,"answer":["1"],"explanation":"NCERT defines solid wastes as everything that goes out in trash.\nMunicipal solid wastes are wastes from homes, offices, stores, schools, hospitals and similar places that the municipality collects and disposes of.\nThey include paper, food wastes, plastics, glass, metals, rubber, leather and textiles. Option (3) fails because they are not only non-biodegradable.\nIndustrial effluents and crop residues are not part of this definition.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-137","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":137,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which one of the following statements about ozone is incorrect?","image":"","options":["The thickness of the ozone layer in a column of air is measured in Dobson units","UV-B is absorbed by the cornea, and high doses can cause inflammation of the cornea called snow-blindness","Ozone in the troposphere is beneficial because it shields living organisms from UV radiation","The Montreal Protocol (1987) was an international treaty to control emission of ozone-depleting substances"],"optionsInImage":false,"answer":["3"],"explanation":"(1) Correct. Ozone layer thickness is expressed in Dobson units.\n(2) Correct. The cornea absorbs UV-B, and a high dose causes snow-blindness and cataract.\n(3) Incorrect. Tropospheric ozone is 'bad ozone', a harmful pollutant. Only stratospheric ozone absorbs UV radiation and protects life.\n(4) Correct. The Montreal Protocol was signed in 1987 and became effective in 1989.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-138","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":138,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: According to the Central Pollution Control Board, particles of about 10 micrometres diameter cause the greatest harm to human health, because larger particles carry more pollutant mass.\nStatement II: Fine particulate matter can be inhaled deep into the lungs and may cause breathing problems, irritation, inflammation, lung damage and premature death.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["4"],"explanation":"Statement I is incorrect. CPCB considers particles 2.5 micrometres or less in diameter (PM 2.5) the most harmful, not 10 micrometre particles.\nStatement II is correct. Being so small, fine particles reach deep into the lungs. There they cause respiratory symptoms, irritation, inflammation, lung damage and premature death.\nThis small size is exactly why PM 2.5, rather than larger particles, is the most harmful.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-139","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":139,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Even small amounts of CFCs reaching the stratosphere can cause extensive and long-lasting degradation of the ozone layer.\nReason (R): Each chlorine atom released from CFCs is used up permanently after reacting with one ozone molecule.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"A is true. UV radiation splits CFCs in the stratosphere and releases Cl atoms, which degrade ozone to molecular oxygen. The resulting damage is large and long-lasting.\nR is false. NCERT states that Cl atoms act only as catalysts and are not consumed in the reaction.\nBecause the chlorine is not used up, one Cl atom can destroy many ozone molecules. A permanently consumed Cl atom could not explain the extensive damage in A.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-140","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":140,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I:\nA. Ahmed Khan\nB. Ramesh Chandra Dagar\nC. Amrita Devi\nD. FOAM (Friends of the Arcata Marsh)\nList-II:\n(i) Integrated organic farming in Sonipat, Haryana\n(ii) Polyblend from recycled plastic for roads in Bangalore\n(iii) Integrated wastewater treatment in California\n(iv) Bishnoi woman who sacrificed her life to protect trees in Rajasthan","image":"","options":["A-i, B-ii, C-iv, D-iii","A-ii, B-i, C-iii, D-iv","A-iv, B-i, C-ii, D-iii","A-ii, B-i, C-iv, D-iii"],"optionsInImage":false,"answer":["4"],"explanation":"A–ii: Ahmed Khan of Bangalore developed polyblend, a powder of recycled modified plastic mixed with bitumen for roads.\nB–i: Ramesh Chandra Dagar practises integrated organic farming in Sonipat.\nC–iv: Amrita Devi Bishnoi gave her life in 1731 protecting khejri trees.\nD–iii: FOAM, a citizens' group, maintains the Arcata (California) marsh wastewater treatment system.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-141","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":141,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Ozone depletion occurs widely in the stratosphere, but it is particularly marked over one region, forming the 'ozone hole'. This region is:","image":"","options":["The Antarctic region","The equatorial region","The Indian subcontinent","The Sahara desert"],"optionsInImage":false,"answer":["1"],"explanation":"NCERT states that ozone depletion is particularly marked over the Antarctic region.\nThere, a large area of thinned ozone layer has formed, commonly called the ozone hole.\nThe other regions listed are not described as sites of an ozone hole.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-142","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":142,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Radiation from nuclear waste causes mutations at a very high rate, and lower doses most often cause cancer. Which method of disposal of nuclear waste has been recommended?","image":"","options":["Dumping untreated waste into deep ocean trenches","Pretreating the waste and storing it in suitably shielded containers buried within rocks about 500 m below the earth's surface","Burning the waste in high-temperature incinerators like those used for hospital waste","Diluting the waste with large volumes of water and releasing it into rivers"],"optionsInImage":false,"answer":["2"],"explanation":"Nuclear waste is extremely damaging. High doses are lethal, and lower doses cause disorders, most often cancer.\nThe recommended method is to pretreat the waste first. It is then stored in suitably shielded containers buried within rocks, about 500 m deep below the earth's surface. This method has met strong public opposition.\nIncineration cannot destroy radioactivity, so option (3) is wrong.\nDumping in the ocean or diluting in rivers spreads radiation to living organisms, so options (1) and (4) are wrong.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-143","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":143,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\n(a) Chipko movement\n(b) Amrita Devi Bishnoi\n(c) Ahmed Khan\n(d) Arcata, California\nList-II\n(i) Polyblend made from recycled plastic waste\n(ii) Integrated wastewater treatment using a series of marshes\n(iii) Village women hugging trees in the Garhwal Himalayas (1974)\n(iv) Sacrifice of life to protect trees in Rajasthan (1731)","image":"","options":["a-iii, b-iv, c-i, d-ii","a-iv, b-iii, c-i, d-ii","a-iii, b-iv, c-ii, d-i","a-iv, b-iii, c-ii, d-i"],"optionsInImage":false,"answer":["1"],"explanation":"(a)-(iii): In the Chipko movement of 1974, women in Garhwal hugged trees to stop them being felled.\n(b)-(iv): In 1731 Amrita Devi Bishnoi hugged a tree to protect it from the king's men in Rajasthan and gave her life.\n(c)-(i): Ahmed Khan of Bangalore developed polyblend, a powder of recycled modified plastic that is mixed with bitumen for roads.\n(d)-(ii): Arcata treated its sewage biologically through six connected marshes.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-144","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":144,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements about open dumps is INCORRECT?","image":"","options":["Burning in open dumps reduces the volume of waste","Waste in open dumps is generally not burnt to completeness","Open dumps often serve as breeding grounds for rats and flies","Open-burning dumps were adopted as a substitute for sanitary landfills"],"optionsInImage":false,"answer":["4"],"explanation":"(1) Correct: burning reduces the volume of waste.\n(2) Correct: the burning is usually incomplete.\n(3) Correct: open dumps breed rats and flies.\n(4) Incorrect: it is the reverse. Sanitary landfills were adopted as the substitute for open-burning dumps.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-145","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":145,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements about the greenhouse effect and global warming are correct?\n(i) Carbon dioxide makes the largest relative contribution to total global warming, about 60%.\n(ii) Without the greenhouse effect, the average surface temperature of the earth would be about $-18^\\circ C$ instead of about $15^\\circ C$.\n(iii) Methane contributes more to global warming than CFCs do.\n(iv) Nitrous oxide contributes about 14% of total global warming.\n(v) Earth's temperature has risen by about $0.6^\\circ C$ during the past century.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: $CO_2$ contributes about 60%.\n(ii) Correct: the greenhouse effect keeps the average temperature near $15^\\circ C$; without it, the temperature would be about $-18^\\circ C$.\n(iii) Correct: methane contributes about 20% and CFCs about 14%.\n(iv) Incorrect: $N_2O$ contributes only about 6%; the 14% figure belongs to CFCs.\n(v) Correct: NCERT notes a rise of about $0.6^\\circ C$ over the last century.\nSo four statements are correct.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-146","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":146,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The auto fuel policy roadmap aims to move from Euro II fuel specifications to its stated goal for sulphur and aromatic content. If the goal is fully achieved, how will diesel change compared with Euro II levels?","image":"","options":["Sulphur falls 7-fold; aromatics fall by 7 percentage points","Sulphur falls 3-fold; aromatics fall by 7 percentage points","Sulphur falls 7-fold; aromatics fall by 35 percentage points","Sulphur falls 3-fold; aromatics fall by 42 percentage points"],"optionsInImage":false,"answer":["1"],"explanation":"Given: under Euro II, diesel sulphur is 350 ppm and aromatics are 42%.\nGoal: sulphur 50 ppm and aromatics 35%.\nSulphur: 350 ÷ 50 = 7, so a 7-fold reduction.\nAromatics: 42 − 35 = 7 percentage points.\nThe 3-fold figure would apply to petrol (150 → 50 ppm), which makes option (2) a trap.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-147","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":147,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: Integrated organic farming is a cyclical, zero-waste procedure in which waste products of one process are used as nutrients for other processes.\nStatement II: In Dagar's farm, crop waste is used only as cattle fodder and cannot serve as an energy source for the farm.","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["2"],"explanation":"Statement I is correct: NCERT defines integrated organic farming as cyclical and zero-waste.\nIn this system, the waste from one process becomes the nutrient input for another, which maximises resource use.\nStatement II is incorrect: crop waste is used to make compost.\nThis compost can serve as a natural fertiliser or be used to generate natural gas for the farm's energy needs.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-148","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":148,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements about air pollution and its control is INCORRECT?","image":"","options":["The Air (Prevention and Control of Pollution) Act came into force in 1981 and was amended in 1987 to include noise as an air pollutant","In an electrostatic precipitator, electrons from the corona give dust particles a net positive charge, so they are attracted to the collecting plates","Air pollutants reduce the growth and yield of crops and can cause premature death of plants","The harmful effects of air pollutants depend on their concentration, the duration of exposure and the organism"],"optionsInImage":false,"answer":["2"],"explanation":"(1) Correct: the Air Act dates from 1981, and the 1987 amendment added noise as an air pollutant.\n(2) Incorrect: electrons attach to the dust particles, so the particles get a net negative charge. The grounded collecting plates then attract them.\n(3) Correct: NCERT lists reduced crop growth and yield, and premature death of plants, as effects of air pollution.\n(4) Correct: the effects depend on concentration, duration of exposure and the organism exposed.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-149","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":149,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Chipko Movement in Garhwal Himalayas\nB. Montreal Protocol signed\nC. National Forest Policy of India\nD. Environment (Protection) Act\nList-II\n(i) 1986\n(ii) 1987\n(iii) 1974\n(iv) 1988","image":"","options":["A-iii, B-ii, C-iv, D-i","A-iii, B-iv, C-ii, D-i","A-i, B-ii, C-iv, D-iii","A-iii, B-i, C-iv, D-ii"],"optionsInImage":false,"answer":["1"],"explanation":"A-iii: the Chipko Movement began in 1974.\nB-ii: the Montreal Protocol was signed in 1987 and came into effect in 1989.\nC-iv: the National Forest Policy dates from 1988.\nD-i: the Environment (Protection) Act was passed in 1986.\nThe tempting swap of 1987 and 1988 (option 2) is wrong.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-150","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":150,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"A thermal power plant passes its exhaust first through an efficient electrostatic precipitator and then through a lime-spray scrubber. Based on NCERT, which component of the gas released from the stack would still be of greatest concern for human health?","image":"","options":["Coarse dust particles","Sulphur dioxide","Very fine particulates of 2.5 micrometres or less","Nitrogen gas"],"optionsInImage":false,"answer":["3"],"explanation":"The electrostatic precipitator removes over 99% of particulate matter, so coarse dust is largely captured.\nThe lime-spray scrubber removes SO$_2$.\nNitrogen is a harmless component of the exhaust.\nNCERT notes that very small particulates are not removed by these precipitators. The CPCB considers PM2.5 the most harmful because it penetrates deep into the lungs.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-151","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":151,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements about electronic wastes (e-wastes) is INCORRECT?","image":"","options":["Irreparable computers and other electronic goods constitute e-wastes","Over half of the e-wastes generated in the developed world are exported to developing countries such as China, India and Pakistan","Metals such as copper, iron, silicon, nickel and gold are recovered during e-waste recycling","Developed countries mostly recycle e-wastes manually, while developing countries use specially built facilities"],"optionsInImage":false,"answer":["4"],"explanation":"(1) Correct: irreparable electronic goods are e-wastes.\n(2) Correct: more than half of the developed world's e-waste is exported, mainly to China, India and Pakistan.\n(3) Correct: copper, iron, silicon, nickel and gold are recovered during recycling.\n(4) Incorrect: the situation is reversed. Developed countries have specially built facilities, and developing countries rely on manual recycling.\nNCERT adds that the eventual solution is eco-friendly recycling.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-152","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":152,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II:\nList-I\n(A) 150 dB or more\n(B) 1987\n(C) Horn-free zone\n(D) Decibel (dB)\nList-II\n(i) Unit used to express sound level\n(ii) Area around hospitals and schools\n(iii) Take-off of a jet plane or rocket\n(iv) Noise included as an air pollutant\nChoose the correct option:","image":"","options":["A-iii, B-iv, C-ii, D-i","A-iv, B-iii, C-ii, D-i","A-iii, B-iv, C-i, D-ii","A-ii, B-iv, C-iii, D-i"],"optionsInImage":false,"answer":["1"],"explanation":"A-iii: a jet plane or rocket taking off produces 150 dB or more.\nB-iv: in 1987 the Air Act was amended to include noise as an air pollutant.\nC-ii: NCERT suggests making hospital and school areas horn-free zones.\nD-i: sound level is measured in decibels.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-153","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":153,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Which of the following statements about heated (thermal) wastewater from thermal power plants is correct?","image":"","options":["It increases the number of organisms that are sensitive to high temperature","It may enhance the growth of plants and fish in extremely cold areas, but only after damaging the native flora and fauna","It is harmless because it contains no chemical pollutants","It mainly causes biomagnification of heavy metals"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT treats heated wastewater from electricity-generating units as a separate category of pollutant. \nIt eliminates or reduces organisms that are sensitive to high temperature, so option 1 is wrong. \nIn extremely cold areas it may boost the growth of plants and fish, but only after harming the indigenous flora and fauna, so option 2 is correct. \nHeat itself is the pollutant, and it is not linked to biomagnification. \nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-154","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":154,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In slash and burn (jhum) agriculture practised in the north-eastern states of India, what serves as the fertiliser for the cleared land?","image":"","options":["Ash of the burnt plant remains","Animal dung collected from the forest","Green manure ploughed into the soil","Silt deposited by flooding rivers"],"optionsInImage":false,"answer":["1"],"explanation":"In jhum cultivation, farmers cut down the forest trees and burn the plant remains.\nThe ash left behind fertilises the soil.\nThe land is then used for farming or cattle grazing for a while before the farmers move to a new patch.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-155","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":155,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Ahmed Khan, a plastic sack manufacturer from Bangalore, developed 'polyblend'. What is polyblend?","image":"","options":["A fine powder of recycled, modified plastic","A biodegradable plastic made from plant starch","A mixture of bitumen and rubber from used tyres","A liquid binder obtained from distillation of crude oil"],"optionsInImage":false,"answer":["1"],"explanation":"NCERT describes polyblend as a fine powder of recycled, modified plastic. Its raw material is plastic film waste.\nThis powder is mixed with bitumen to lay roads.\nOption (3) is tempting because polyblend is used along with bitumen. However, polyblend itself is the plastic powder, not a bitumen–rubber mix.\nOptions (2) and (4) describe unrelated materials.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-156","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":156,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Over-cultivation, unrestricted grazing, deforestation and poor irrigation produce arid patches of land. When large barren patches extend and meet over time, a desert forms. This process is called:","image":"","options":["Waterlogging","Salinisation","Desertification","Eutrophication"],"optionsInImage":false,"answer":["3"],"explanation":"Fertile top-soil takes centuries to form but is easily lost through human misuse of land.\nThe resulting arid patches can extend and merge into a desert. This is desertification.\nWaterlogging and salinisation come from irrigation without proper drainage.\nEutrophication is nutrient enrichment of water bodies.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-157","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":157,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Domestic sewage contains only about 0.1% impurities, but this is enough to make it unfit for human use. These impurities consist mainly of:","image":"","options":["heavy metal ions such as mercury and cadmium","non-biodegradable plastics and polythene","radioactive substances","biodegradable organic matter"],"optionsInImage":false,"answer":["4"],"explanation":"According to NCERT, domestic sewage mainly contains biodegradable organic matter, which microbes can readily decompose.\nThis is the reason sewage raises the BOD of the water body that receives it.\nHeavy metals are characteristic of industrial effluents, not domestic sewage.\nPlastics and radioactive wastes are separate pollution problems.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-158","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":158,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In which year did India pass the Water (Prevention and Control of Pollution) Act to safeguard its water resources?","image":"","options":["1981","1974","1986","1987"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT states that the Government of India passed the Water (Prevention and Control of Pollution) Act in 1974 to safeguard water resources.\nThe year 1981 is the tempting wrong choice. That is the year of the Air (Prevention and Control of Pollution) Act.\nThe Environment (Protection) Act came in 1986.\nIn 1987 the Air Act was amended to include noise.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-159","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":159,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The thickness of the ozone layer in a column of air from the ground to the top of the atmosphere is expressed in:","image":"","options":["Decibels (dB)","Dobson units (DU)","Parts per million (ppm)","Micrometres ($\\mu m$)"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT states that the thickness of the ozone in a column of air from the ground to the top of the atmosphere is measured in Dobson units (DU).\nDecibels measure the loudness of sound, which is relevant to noise pollution, not ozone.\nMicrometres are used for particle size, such as PM 2.5.\nParts per million is a general concentration unit. It is not the unit NCERT uses for ozone layer thickness.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-160","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":160,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Assertion (A): Irrigation without proper drainage of water has led to soil salinity in many areas after the Green Revolution.\nReason (R): Waterlogging draws salt to the surface of the soil, where it is deposited as a thin crust or collects at the roots of plants.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"A is true: poor drainage during irrigation causes waterlogging, which is one of the problems that came with the Green Revolution.\nR is true: waterlogging brings salts up to the surface. There they form a thin crust or accumulate at the roots and harm crops.\nR explains how waterlogging leads to salinity, so it correctly explains A.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-161","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":161,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II:\nList-I\n(A) BOD\n(B) Algal bloom\n(C) Cultural eutrophication\n(D) Eichhornia\nList-II\n(i) Excessive growth of planktonic free-floating algae\n(ii) Human-accelerated nutrient enrichment and ageing of a lake\n(iii) Measure of biodegradable organic matter in water\n(iv) 'Terror of Bengal'","image":"","options":["A-iii, B-i, C-ii, D-iv","A-i, B-iii, C-iv, D-ii","A-iii, B-ii, C-i, D-iv","A-ii, B-i, C-iii, D-iv"],"optionsInImage":false,"answer":["1"],"explanation":"(A) BOD indicates the amount of biodegradable organic matter, because it measures the oxygen microbes need to oxidise that matter. So A-iii.\n(B) An algal bloom is the excess growth of planktonic algae in nutrient-rich water. So B-i.\n(C) Cultural or accelerated eutrophication is lake ageing sped up by human effluents. So C-ii.\n(D) Eichhornia is the 'Terror of Bengal'. So D-iv.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-162","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":162,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The Montreal Protocol, an international treaty to control the emission of ozone-depleting substances, was signed in the year:","image":"","options":["1989","1997","1987","1992"],"optionsInImage":false,"answer":["3"],"explanation":"The Montreal Protocol was signed at Montreal, Canada, in 1987.\nIt came into effect in 1989, so 1989 is the tempting wrong option.\nIts purpose was to control the emission of ozone-depleting substances such as CFCs.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-163","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":163,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following statements are correct?\n(i) Without the greenhouse effect, the average temperature at Earth's surface would be about –18 °C instead of about 15 °C.\n(ii) After carbon dioxide and methane, CFCs make the next largest contribution to global warming.\n(iii) Chlorine atoms released from CFCs in the stratosphere degrade ozone, acting as catalysts that are not themselves consumed.\n(iv) A high dose of UV-B can cause inflammation of the cornea, called snow-blindness.\n(v) The ozone hole is most marked over the Arctic region.\n(vi) Ozone in the troposphere is called 'good ozone' because it absorbs UV radiation.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: the values are about 15 °C with the greenhouse effect and –18 °C without it.\n(ii) Correct: CO$_2$ contributes about 60%, CH$_4$ about 20%, CFCs about 14% and N$_2$O about 6%.\n(iii) Correct: chlorine acts as a catalyst and is not consumed.\n(iv) Correct: high-dose UV-B causes snow-blindness.\n(v) Incorrect: the ozone hole is most marked over Antarctica.\n(vi) Incorrect: stratospheric ozone is the 'good' ozone; tropospheric ozone is 'bad'.\nFour statements are correct.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-164","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":164,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\n(A) Amrita Devi Bishnoi\n(B) Chipko movement\n(C) Joint Forest Management\n(D) National Forest Policy\nList-II\n(i) Introduced in the 1980s, involving local communities in protecting forests\n(ii) Recommended 33% forest cover for the plains\n(iii) Sacrifice at Khejarli, Rajasthan, in 1731\n(iv) Women hugged trees in the Garhwal Himalayas in 1974","image":"","options":["A-iii, B-iv, C-i, D-ii","A-iv, B-iii, C-ii, D-i","A-iii, B-iv, C-ii, D-i","A-i, B-iv, C-iii, D-ii"],"optionsInImage":false,"answer":["1"],"explanation":"A-iii: Amrita Devi hugged a tree at Khejarli in 1731 and gave her life with her daughters and many other Bishnois.\nB-iv: In the Chipko movement (1974, Garhwal), women hugged trees.\nC-i: Joint Forest Management was introduced in the 1980s and involves local communities.\nD-ii: The National Forest Policy (1988) recommended 33% forest cover for the plains (67% for hills).\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-165","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":165,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"The flue gas from a thermal power plant contains both fly ash and sulphur dioxide. Consider the following statements about the devices used to clean it:\n(i) In an electrostatic precipitator, electrode wires kept at several thousand volts produce a corona that releases electrons.\n(ii) These electrons attach to dust particles and give them a net positive charge.\n(iii) The collecting plates of the precipitator are grounded and attract the charged dust particles.\n(iv) The electrostatic precipitator is the main device for removing $SO_2$ from the exhaust.\n(v) A scrubber removes $SO_2$ by passing the exhaust through a spray of water or lime.\nWhich of the above statements are correct?","image":"","options":["(i), (ii) and (iii) only","(i), (iii) and (v) only","(ii), (iv) and (v) only","(i), (iii), (iv) and (v) only"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: high-voltage electrode wires produce a corona that releases electrons.\n(ii) Incorrect: the electrons give dust particles a net negative charge.\n(iii) Correct: the grounded collecting plates attract the charged particles. In this way the precipitator removes over 99% of particulate matter.\n(iv) Incorrect: the precipitator removes particulates, not gases like $SO_2$.\n(v) Correct: a scrubber sprays water or lime to remove $SO_2$.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"hard"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-166","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":166,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"How many of the following are consequences of deforestation as described in NCERT?\n(i) Enhanced carbon dioxide concentration in the atmosphere\n(ii) Loss of biodiversity due to habitat destruction\n(iii) Disturbance of the hydrologic cycle\n(iv) Increase in the fertility of top-soil\n(v) Soil erosion, leading to desertification in extreme cases\n(vi) Decrease in atmospheric carbon dioxide because burnt trees release oxygen","image":"","options":["Three","Four","Five","Six"],"optionsInImage":false,"answer":["2"],"explanation":"(i) Correct: trees store a lot of carbon in their biomass, and this storage is lost.\n(ii) Correct: habitats are destroyed, so biodiversity is lost.\n(iii) Correct: the water cycle is disturbed.\n(iv) Incorrect: top-soil is eroded, so its fertility does not increase.\n(v) Correct: soil erosion can lead to desertification.\n(vi) Incorrect: deforestation raises atmospheric CO2; it does not lower it.\nFour statements are correct.\nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-167","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":167,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to the Central Pollution Control Board (CPCB), particulate matter of which size is responsible for causing the greatest harm to human health?","image":"","options":["10 micrometres or more in diameter","5 micrometres in diameter","7.5 micrometres in diameter","2.5 micrometres or less in diameter"],"optionsInImage":false,"answer":["4"],"explanation":"The CPCB identifies particles 2.5 micrometres or less in diameter (PM2.5) as the most harmful to human health.\nThese fine particles can be inhaled deep into the lungs.\nLarger particles such as PM10 are mostly trapped higher up in the respiratory tract, so they cause less harm.\nAnswer: (4)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-168","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":168,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Match List-I with List-II.\nList-I\n(a) Bishnoi sacrifice for trees\n(b) Chipko movement\n(c) Joint Forest Management introduced\n(d) National Forest Policy\nList-II\n(i) 1974\n(ii) 1988\n(iii) 1731\n(iv) 1980s","image":"","options":["a-iii, b-i, c-iv, d-ii","a-iii, b-iv, c-i, d-ii","a-i, b-iii, c-ii, d-iv","a-iii, b-i, c-ii, d-iv"],"optionsInImage":false,"answer":["1"],"explanation":"(a) In 1731, Amrita Devi and other Bishnois gave their lives to protect trees near Jodhpur: iii.\n(b) The Chipko movement in the Garhwal Himalayas began in 1974: i.\n(c) Joint Forest Management was introduced by the Government of India in the 1980s: iv.\n(d) The National Forest Policy was framed in 1988: ii.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-169","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":169,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Consider the following statements about the integrated organic farming practised by Ramesh Chandra Dagar in Sonipat, Haryana:\n(i) His farm combines bee-keeping, dairy management, water harvesting, composting and agriculture.\n(ii) Cattle excreta (dung) is used as manure, so chemical fertilisers are not needed.\n(iii) Crop waste can be turned into compost or used to generate natural gas for the farm's energy needs.\n(iv) Each component works independently of the others, so the waste of one process is not used by another.\nHow many of the above statements are correct?","image":"","options":["1","2","3","4"],"optionsInImage":false,"answer":["3"],"explanation":"(i) Correct: Dagar's farm links bee-keeping, dairy, water harvesting, composting and agriculture.\n(ii) Correct: cattle dung serves as manure, which removes the need for chemical fertilisers.\n(iii) Correct: crop waste is composted into natural fertiliser or used to produce natural gas for energy.\n(iv) Incorrect: the processes form a chain that supports one another. The waste of one becomes the input of another, so the system is economical and sustainable.\nSo three statements are correct.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"medium"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-170","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":170,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"According to NCERT, which of the following is a major cause of atmospheric pollution, at least in metro cities?","image":"","options":["Automobiles","Domestic cooking on LPG","Agricultural irrigation","Hydroelectric power stations"],"optionsInImage":false,"answer":["1"],"explanation":"NCERT states that automobiles are a major cause of atmospheric pollution, at least in metro cities.\nAs the number of vehicles grows, the problem is spreading to other cities as well.\nLPG burns comparatively cleanly. Irrigation and hydroelectric stations are not major sources of air pollutants.\nAnswer: (1)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-171","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":171,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"Statement I: Eichhornia crassipes, the world's most problematic aquatic weed, is also known as the 'Terror of Bengal'.\nStatement II: Water hyacinth grows best in nutrient-poor water and therefore rarely disturbs the ecosystem of a water body.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Statement I is correct: water hyacinth is called the 'Terror of Bengal' and is described as the world's most problematic aquatic weed.\nStatement II is incorrect: it grows abundantly in eutrophic (nutrient-rich) water.\nIt also upsets the ecosystem by causing imbalance in the dynamics of the water body.\nAnswer: (3)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"},{"id":"NCERT12-BIO-ENVIRONMENTAL-ISSUES-172","exam":"NEET","year":null,"paper":"Practice · Environmental Issues","qno":172,"subject":"Biology","section":"","part":"","chapter":"Environmental Issues","type":"mcq","question":"In the integrated wastewater treatment developed at Arcata, California, what was used after conventional treatment to remove the pollutants that remained, such as dissolved heavy metals?","image":"","options":["Incinerators that burn the remaining sludge","A series of connected natural marshes seeded with suitable plants, algae, fungi and bacteria","Anaerobic sludge digesters that produce biogas","Repeated chlorination in closed tanks"],"optionsInImage":false,"answer":["2"],"explanation":"At Arcata, a citizens' group worked with scientists from Humboldt State University to treat sewage within a natural system. \nConventional sedimentation, filtering and chlorine treatment came first, but dissolved heavy metals still remained in the water. \nTo remove them, the water was passed through six connected marshes covering about 60 hectares. These marshes were seeded with plants, algae, fungi and bacteria that neutralise, absorb and assimilate the pollutants. \nRepeated chlorination is wrong because chlorine does not remove dissolved heavy metals. \nAnswer: (2)","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 12 Biology (pre-2023 edition), Ch 16 · Environmental Issues","difficulty":"easy"}]});
